package br.com.vitaflow.fhirfacade.traducao;

import java.time.ZoneId;

/**
 * URLs de identificacao usadas pela fachada.
 *
 * <p>CPF e CNS vem do catalogo oficial da RNDS, conferido em 24/08/2026 contra
 * https://rnds-fhir.saude.gov.br/. Os valores locais do Santa Aurora ainda
 * dependem de confirmacao da Coordenacao de TI (ver design.md, Decisao 2).
 */
public final class Sistemas {

    /** RNDS: NamingSystem-cpf, uniqueId do tipo uri. */
    public static final String CPF = "http://rnds.saude.gov.br/fhir/r4/NamingSystem/cpf";

    /** RNDS: NamingSystem-cns, uniqueId do tipo uri. */
    public static final String CNS = "http://rnds.saude.gov.br/fhir/r4/NamingSystem/cns";

    /** Codigo interno do SIGH. Unico identificador presente em 100% da base. */
    public static final String CD_PACIENTE = "http://santaaurora.org.br/fhir/sid/sigh-cd-paciente";

    /**
     * Preserva o valor bruto de tp_sexo quando ele nao e M nem F.
     * Existe porque o significado de 'I' e uma pergunta aberta com a Medsys:
     * se a resposta vier, a correcao do mapeamento vira mudanca de codigo, e
     * nao reconciliacao com a origem.
     */
    public static final String EXT_TP_SEXO_ORIGEM =
            "http://santaaurora.org.br/fhir/StructureDefinition/sigh-tp-sexo-origem";

    /**
     * O SIGH grava TIMESTAMP sem fuso. A fachada fixa um fuso unico para que o
     * filtro de _lastUpdated e o valor exposto em meta.lastUpdated sejam
     * derivados da mesma conversao — se divergissem, o consumidor que guarda a
     * maior marca d'agua entraria em laco ou perderia registros.
     */
    public static final ZoneId ZONA_DA_ORIGEM = ZoneId.of("America/Recife");

    private Sistemas() {
    }
}

