import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

/**
 * Leitura do cadastro do SIGH.
 *
 * <p>SQL explicito e escrito a mao, por decisao de design (design.md, Decisao 1):
 * todo o acoplamento ao modelo do fornecedor fica concentrado aqui, que e
 * exatamente o arquivo que os testes de contrato vigiam.
 *
 * <p>Restricoes que valem para toda consulta deste arquivo:
 * <ul>
 *   <li>RA-01/RA-04: somente SELECT. Nenhum comando de escrita, em nenhuma forma.</li>
 *   <li>Producao roda PostgreSQL 12.14 — nada posterior ao 12 pode aparecer aqui.
 *       Nada de FETCH FIRST ... WITH TIES, nada de funcoes de 13+.</li>
 *   <li>PD-03: nm_mae NAO consta de nenhuma lista de colunas.</li>
 * </ul>
 */
@Repository
public class PacienteRepository {

    /**
     * Colunas lidas de sigh.paciente. Note a ausencia de nm_mae — PD-03.
     * dt_cadastro entra apenas dentro do COALESCE, nunca sozinha.
     */
    static final String COLUNAS_PACIENTE = """
            cd_paciente, nm_paciente, nm_social, dt_nascimento, tp_sexo,
            nr_cpf, nr_cns, st_ativo, dt_obito,
            COALESCE(dt_atualizacao, dt_cadastro) AS dt_referencia
            """;

    private static final String SELECT_PACIENTE = "SELECT " + COLUNAS_PACIENTE + " FROM sigh.paciente ";

    private final JdbcTemplate jdbc;

    public PacienteRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static final RowMapper<PacienteRegistro> PACIENTE = (rs, n) -> new PacienteRegistro(
            rs.getInt("cd_paciente"),
            rs.getString("nm_paciente"),
            rs.getString("nm_social"),
            data(rs, "dt_nascimento"),
            rs.getString("tp_sexo"),
            rs.getString("nr_cpf"),
            rs.getString("nr_cns"),
            rs.getString("st_ativo"),
            data(rs, "dt_obito"),
            instante(rs, "dt_referencia"));

    private static LocalDate data(ResultSet rs, String coluna) throws SQLException {
        var valor = rs.getDate(coluna);
        return valor == null ? null : valor.toLocalDate();
    }

    private static LocalDateTime instante(ResultSet rs, String coluna) throws SQLException {
        var valor = rs.getTimestamp(coluna);
        return valor == null ? null : valor.toLocalDateTime();
    }

    public Optional<PacienteRegistro> porCodigo(int cdPaciente) {
        var achados = jdbc.query(SELECT_PACIENTE + "WHERE cd_paciente = ?", PACIENTE, cdPaciente);
        return achados.stream().findFirst();
    }

    /**
     * Busca por CPF ou por CNS.
     *
     * <p>Devolve lista, e nao um unico registro, porque a unicidade do CPF nao e
     * garantida pelo banco: ix_paciente_cpf e indice NAO unico e o dicionario
     * (Nota 1) delega a unicidade a aplicacao. A fachada nao escolhe um.
     */
    public List<PacienteRegistro> porCpf(String cpf) {
        return jdbc.query(SELECT_PACIENTE + "WHERE nr_cpf = ? ORDER BY cd_paciente", PACIENTE, cpf);
    }

    public List<PacienteRegistro> porCns(String cns) {
        return jdbc.query(SELECT_PACIENTE + "WHERE nr_cns = ? ORDER BY cd_paciente", PACIENTE, cns);
    }

    public List<PacienteRegistro> porDataNascimento(LocalDate nascimento) {
        return jdbc.query(SELECT_PACIENTE + "WHERE dt_nascimento = ? ORDER BY cd_paciente",
                PACIENTE, java.sql.Date.valueOf(nascimento));
    }

    /**
     * Janela de sincronizacao incremental sobre COALESCE(dt_atualizacao, dt_cadastro).
     *
     * <p>O mesmo COALESCE alimenta o filtro e o meta.lastUpdated exposto. Se as
     * duas expressoes divergissem, o consumidor que guarda a maior marca d'agua
     * recebida entraria em laco ou perderia registros na proxima janela.
     */
    public List<PacienteRegistro> alteradosNaJanela(LocalDateTime de, LocalDateTime ate, int limite) {
        var sql = new StringBuilder(SELECT_PACIENTE + "WHERE 1 = 1 ");
        var parametros = new ArrayList<Object>();
        if (de != null) {
            sql.append("AND COALESCE(dt_atualizacao, dt_cadastro) >= ? ");
            parametros.add(java.sql.Timestamp.valueOf(de));
        }
        if (ate != null) {
            sql.append("AND COALESCE(dt_atualizacao, dt_cadastro) <= ? ");
            parametros.add(java.sql.Timestamp.valueOf(ate));
        }
        sql.append("ORDER BY COALESCE(dt_atualizacao, dt_cadastro), cd_paciente LIMIT ?");
        parametros.add(limite);
        return jdbc.query(sql.toString(), PACIENTE, parametros.toArray());
    }

    /**
     * Busca por nome, insensivel a caixa e a acentuacao, sobre nome civil e nome social.
     *
     * <p>A normalizacao acontece aqui, na aplicacao, e nao no banco: RF-03 exige
     * insensibilidade a acento, RA-02 proibe instalar unaccent, e integracao_ro
     * nem privilegio para isso tem. O custo e varredura completa — declarado na
     * spec e medido pela tarefa 9.3.
     *
     * <p>A varredura examina toda a tabela, mas so materializa {@code limite}
     * registros. {@link ResultadoBusca#examinados()} devolve o custo real da
     * varredura para que ele possa ser medido em vez de estimado.
     */
    @Transactional(readOnly = true)
    public ResultadoBusca porNome(String termo, int limite) {
        var alvo = TextoNormalizado.normalizar(termo);
        var encontrados = new ArrayList<PacienteRegistro>();
        var examinados = new int[1];

        jdbc.query(conexao -> {
            var ps = conexao.prepareStatement(SELECT_PACIENTE + "ORDER BY cd_paciente");
            // Sem fetch size o driver traz a tabela inteira de uma vez.
            ps.setFetchSize(200);
            return ps;
        }, (ResultSet rs) -> {
            examinados[0]++;
            if (encontrados.size() >= limite) {
                return;
            }
            var civil = TextoNormalizado.normalizar(rs.getString("nm_paciente"));
            var social = TextoNormalizado.normalizar(rs.getString("nm_social"));
            if (civil.contains(alvo) || social.contains(alvo)) {
                encontrados.add(PACIENTE.mapRow(rs, encontrados.size()));
            }
        });

        return new ResultadoBusca(List.copyOf(encontrados), examinados[0]);
    }

    /** Resultado de uma busca com varredura, junto do custo que ela teve. */
    public record ResultadoBusca(List<PacienteRegistro> registros, int examinados) {
    }

    public List<ContatoRegistro> contatosDe(int cdPaciente) {
        return jdbc.query("""
                SELECT cd_contato, cd_paciente, tp_contato, ds_contato, st_principal
                  FROM sigh.paciente_contato
                 WHERE cd_paciente = ?
                 ORDER BY cd_contato
                """, (rs, n) -> new ContatoRegistro(
                rs.getInt("cd_contato"),
                rs.getInt("cd_paciente"),
                rs.getString("tp_contato"),
                rs.getString("ds_contato"),
                rs.getString("st_principal")), cdPaciente);
    }

    /**
     * Enderecos com o municipio resolvido.
     *
     * <p>LEFT JOIN, e nao INNER: a Nota 5 do dicionario avisa que municipio_ibge
     * nao e atualizada automaticamente. Com INNER, um municipio novo faria o
     * endereco inteiro desaparecer; com LEFT, some apenas o nome da cidade.
     */
    public List<EnderecoRegistro> enderecosDe(int cdPaciente) {
        return jdbc.query("""
                SELECT e.cd_endereco, e.cd_paciente, e.ds_logradouro, e.nr_numero,
                       e.ds_complemento, e.nm_bairro, e.cd_municipio_ibge,
                       m.nm_municipio, e.sg_uf, e.nr_cep, e.st_principal
                  FROM sigh.paciente_endereco e
                  LEFT JOIN sigh.municipio_ibge m
                         ON m.cd_municipio_ibge = e.cd_municipio_ibge
                 WHERE e.cd_paciente = ?
                 ORDER BY e.cd_endereco
                """, (rs, n) -> {
            var codigoIbge = rs.getInt("cd_municipio_ibge");
            return new EnderecoRegistro(
                    rs.getInt("cd_endereco"),
                    rs.getInt("cd_paciente"),
                    rs.getString("ds_logradouro"),
                    rs.getString("nr_numero"),
                    rs.getString("ds_complemento"),
                    rs.getString("nm_bairro"),
                    rs.wasNull() ? null : codigoIbge,
                    rs.getString("nm_municipio"),
                    rs.getString("sg_uf"),
                    rs.getString("nr_cep"),
                    rs.getString("st_principal"));
        }, cdPaciente);
    }

    /** Usado apenas pelos testes de contrato: valores de dominio que a Medsys mantem. */
    public List<Map<String, Object>> dominios() {
        return jdbc.queryForList(
                "SELECT cd_dominio, cd_valor FROM sigh.de_para_dominio ORDER BY cd_dominio, cd_valor");
    }
}

