package br.com.vitaflow.fhirfacade.traducao;

/**
 * Normalizacao de telefone para E.164.
 *
 * <p>A base de homologacao tem cinco formatos convivendo — (71)22769309,
 * 7125706473, (71) 3119-8500, 71-2208-1233 e +55 71 924465777 — e a contagem de
 * digitos tambem varia: celulares com 11 e com 13, fixos com 10 e com 12.
 *
 * <p>Regra: 10 e 11 digitos sao numero nacional (DDD + assinante) e recebem o
 * codigo do Brasil; 12 e 13 digitos ja trazem o 55. Qualquer outra contagem nao
 * e inferivel — e a fachada NAO inventa prefixo. Nesse caso devolve nulo e o
 * chamador emite o valor de origem como esta.
 */
public final class TelefoneNormalizado {

    public static String paraE164(String bruto) {
        if (bruto == null) {
            return null;
        }
        var digitos = bruto.replaceAll("\\D", "");
        return switch (digitos.length()) {
            case 10, 11 -> "+55" + digitos;
            case 12, 13 -> digitos.startsWith("55") ? "+" + digitos : null;
            default -> null;
        };
    }

    private TelefoneNormalizado() {
    }
}

