package br.com.vitaflow.fhirfacade.seguranca;

import java.util.regex.Pattern;

/**
 * Redacao central de CPF em qualquer saida de log.
 *
 * <p>RNF-05 e PD-04 proibem CPF em log. A fachada ja evita registrar o valor em
 * cada ponto de chamada, mas sanitizacao espalhada e exatamente onde esse tipo
 * de vazamento nasce — basta um log novo escrito sem atencao. Este sanitizador
 * e aplicado pelo layout do Logback, depois da montagem da mensagem, de modo que
 * nenhuma linha escapa dele.
 *
 * <p>O padrao cobre CPF com e sem mascara. A checagem de fronteira evita
 * confundir com CNS, que tem 15 digitos, e com o codigo interno, que tem 5.
 */
public final class LogSanitizador {

    public static final String MARCA = "[CPF-REDIGIDO]";

    private static final Pattern CPF = Pattern.compile(
            "(?<![0-9])(?:[0-9]{3}\\.[0-9]{3}\\.[0-9]{3}-[0-9]{2}|[0-9]{11})(?![0-9])");

    public static String redigir(String texto) {
        if (texto == null || texto.isEmpty()) {
            return texto;
        }
        return CPF.matcher(texto).replaceAll(MARCA);
    }

    private LogSanitizador() {
    }
}

