package br.com.vitaflow.fhirfacade.traducao;

import br.com.vitaflow.fhirfacade.origem.ContatoRegistro;
import br.com.vitaflow.fhirfacade.origem.EnderecoRegistro;
import br.com.vitaflow.fhirfacade.origem.PacienteRegistro;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import org.hl7.fhir.r4.model.Address;
import org.hl7.fhir.r4.model.ContactPoint;
import org.hl7.fhir.r4.model.DateTimeType;
import org.hl7.fhir.r4.model.Enumerations.AdministrativeGender;
import org.hl7.fhir.r4.model.HumanName;
import org.hl7.fhir.r4.model.Identifier;
import org.hl7.fhir.r4.model.Patient;
import org.hl7.fhir.r4.model.StringType;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

/**
 * Traducao de uma linha do SIGH para Patient do FHIR R4.
 *
 * <p>Cada regra nao obvia daqui corresponde a uma divergencia registrada na
 * spec. Nenhuma delas e "detalhe de implementacao".
 */
@Component
public class PacienteMapper {

    private static final Logger log = LoggerFactory.getLogger(PacienteMapper.class);

    public Patient paraPatient(PacienteRegistro registro,
                               List<ContatoRegistro> contatos,
                               List<EnderecoRegistro> enderecos) {
        var paciente = new Patient();

        // cd_paciente e a unica coluna presente em 100% da base. A ata de 14/07
        // fechou "chave = CPF"; o dado (15,5% sem CPF) revogou essa decisao.
        paciente.setId(String.valueOf(registro.cdPaciente()));

        if (registro.ultimaAtualizacao() != null) {
            paciente.getMeta().setLastUpdated(
                    Date.from(registro.ultimaAtualizacao()
                            .atZone(Sistemas.ZONA_DA_ORIGEM).toInstant()));
        }

        aplicarIdentificadores(paciente, registro);
        aplicarNomes(paciente, registro);
        aplicarSexo(paciente, registro);
        aplicarNascimento(paciente, registro);
        aplicarSituacaoEObito(paciente, registro);
        aplicarContatos(paciente, contatos);
        aplicarEnderecos(paciente, enderecos);

        return paciente;
    }

    /**
     * O codigo interno sempre; CPF e CNS apenas quando existem.
     *
     * <p>Nada de entrada com valor vazio: um identifier sem value e pior que
     * identifier nenhum, porque o consumidor tenta casar por ele.
     */
    private void aplicarIdentificadores(Patient paciente, PacienteRegistro registro) {
        paciente.addIdentifier(new Identifier()
                .setSystem(Sistemas.CD_PACIENTE)
                .setValue(String.valueOf(registro.cdPaciente())));

        if (preenchido(registro.nrCpf())) {
            paciente.addIdentifier(new Identifier()
                    .setSystem(Sistemas.CPF)
                    .setValue(registro.nrCpf().trim()));
        }
        if (preenchido(registro.nrCns())) {
            paciente.addIdentifier(new Identifier()
                    .setSystem(Sistemas.CNS)
                    .setValue(registro.nrCns().trim()));
        }
    }

    /**
     * Nome social com precedencia de exibicao, nome civil sempre disponivel.
     *
     * <p>Decreto 8.727/2016. O comentario do DDL do fornecedor cita a Lei
     * 18.911/2021, que e estadual de Sao Paulo — referencia errada, nao
     * reproduzida aqui (o hospital fica em Pernambuco).
     */
    private void aplicarNomes(Patient paciente, PacienteRegistro registro) {
        if (preenchido(registro.nmSocial())) {
            paciente.addName(new HumanName()
                    .setUse(HumanName.NameUse.USUAL)
                    .setText(registro.nmSocial().trim()));
        }
        if (preenchido(registro.nmPaciente())) {
            paciente.addName(new HumanName()
                    .setUse(HumanName.NameUse.OFFICIAL)
                    .setText(registro.nmPaciente().trim()));
        }
    }

    /**
     * M/F traduzem direto. Qualquer outra coisa vira unknown — nunca other.
     *
     * <p>'other' no FHIR afirma que a pessoa nao e masculino nem feminino. E uma
     * afirmacao positiva sobre a pessoa. Ninguem na Medsys sabe o que 'I'
     * significa (nota de campo, 18/07), entao essa afirmacao nao pode ser feita.
     * O valor bruto vai numa extensao para que a correcao, se o fornecedor
     * responder, seja mudanca de codigo e nao reconciliacao com a origem.
     */
    private void aplicarSexo(Patient paciente, PacienteRegistro registro) {
        var bruto = registro.tpSexo() == null ? null : registro.tpSexo().trim();

        var genero = switch (bruto == null ? "" : bruto.toUpperCase()) {
            case "M" -> AdministrativeGender.MALE;
            case "F" -> AdministrativeGender.FEMALE;
            default -> AdministrativeGender.UNKNOWN;
        };
        paciente.setGender(genero);

        boolean traduzidoSemPerda = "M".equalsIgnoreCase(bruto) || "F".equalsIgnoreCase(bruto);
        if (bruto != null && !bruto.isEmpty() && !traduzidoSemPerda) {
            paciente.getGenderElement().addExtension(
                    Sistemas.EXT_TP_SEXO_ORIGEM, new StringType(bruto));
        }
    }

    private void aplicarNascimento(Patient paciente, PacienteRegistro registro) {
        if (registro.dtNascimento() != null) {
            paciente.getBirthDateElement().setValueAsString(registro.dtNascimento().toString());
        }
    }

    /**
     * st_ativo e dt_obito sao independentes. Nunca colapsados.
     *
     * <p>9 dos 15 inativos da base de homologacao estao vivos. Tratar
     * st_ativo='N' como obito marcaria 60% dos inativos como falecidos.
     *
     * <p>Quando nao ha dt_obito, o elemento e omitido em vez de afirmar
     * deceasedBoolean=false: a fachada nao tem como saber se o SIGH registra
     * todos os obitos, e afirmar "nao faleceu" seria uma alegacao sem lastro.
     */
    private void aplicarSituacaoEObito(Patient paciente, PacienteRegistro registro) {
        var ativo = registro.stAtivo() == null ? null : registro.stAtivo().trim().toUpperCase();
        if ("S".equals(ativo)) {
            paciente.setActive(true);
        } else if ("N".equals(ativo)) {
            paciente.setActive(false);
        }

        if (registro.dtObito() == null) {
            return;
        }

        // Par de datas logicamente impossivel. Afirmar o obito seria pior que
        // omiti-lo: um consumidor pode encerrar acompanhamento com base nisso.
        if (registro.dtNascimento() != null && registro.dtObito().isBefore(registro.dtNascimento())) {
            log.warn("Inconsistencia temporal na origem: data de obito anterior a de nascimento. "
                    + "Paciente {} — elemento deceased omitido do recurso.", registro.cdPaciente());
            return;
        }

        paciente.setDeceased(new DateTimeType(registro.dtObito().toString()));
    }

    private void aplicarContatos(Patient paciente, List<ContatoRegistro> contatos) {
        for (var contato : contatos) {
            if (!preenchido(contato.dsContato())) {
                continue;
            }
            var ponto = new ContactPoint();
            var tipo = contato.tpContato() == null ? "" : contato.tpContato().trim().toUpperCase();

            switch (tipo) {
                case "CEL" -> ponto.setSystem(ContactPoint.ContactPointSystem.PHONE)
                        .setUse(ContactPoint.ContactPointUse.MOBILE);
                case "RES" -> ponto.setSystem(ContactPoint.ContactPointSystem.PHONE)
                        .setUse(ContactPoint.ContactPointUse.HOME);
                case "COM" -> ponto.setSystem(ContactPoint.ContactPointSystem.PHONE)
                        .setUse(ContactPoint.ContactPointUse.WORK);
                case "EML" -> ponto.setSystem(ContactPoint.ContactPointSystem.EMAIL);
                // A tabela de dominios da Medsys ja se mostrou desatualizada.
                // Valor novo cai aqui, preservado, em vez de sumir.
                default -> ponto.setSystem(ContactPoint.ContactPointSystem.OTHER);
            }

            var bruto = contato.dsContato().trim();
            if (ponto.getSystem() == ContactPoint.ContactPointSystem.PHONE) {
                var e164 = TelefoneNormalizado.paraE164(bruto);
                ponto.setValue(e164 != null ? e164 : bruto);
            } else {
                ponto.setValue(bruto);
            }

            // Nota 4 do dicionario: pode nao haver principal, ou haver mais de um.
            // Ambos recebem rank 1; a fachada nao desempata nem descarta.
            if ("S".equalsIgnoreCase(trim(contato.stPrincipal()))) {
                ponto.setRank(1);
            }
            paciente.addTelecom(ponto);
        }
    }

    private void aplicarEnderecos(Patient paciente, List<EnderecoRegistro> enderecos) {
        var ordenados = new ArrayList<>(enderecos);
        // Principal primeiro: Address nao tem rank, entao a ordem e o unico sinal.
        ordenados.sort((a, b) -> Boolean.compare(
                !"S".equalsIgnoreCase(trim(a.stPrincipal())),
                !"S".equalsIgnoreCase(trim(b.stPrincipal()))));

        for (var origem : ordenados) {
            var endereco = new Address();

            var primeiraLinha = new StringBuilder();
            if (preenchido(origem.dsLogradouro())) {
                primeiraLinha.append(origem.dsLogradouro().trim());
            }
            if (preenchido(origem.nrNumero())) {
                if (primeiraLinha.length() > 0) {
                    primeiraLinha.append(", ");
                }
                primeiraLinha.append(origem.nrNumero().trim());
            }
            if (primeiraLinha.length() > 0) {
                endereco.addLine(primeiraLinha.toString());
            }
            if (preenchido(origem.dsComplemento())) {
                endereco.addLine(origem.dsComplemento().trim());
            }

            if (preenchido(origem.nmBairro())) {
                endereco.setDistrict(origem.nmBairro().trim());
            }
            // Nulo quando cd_municipio_ibge nao consta de municipio_ibge.
            // Some so a cidade; o resto do endereco continua util.
            if (preenchido(origem.nmMunicipio())) {
                endereco.setCity(origem.nmMunicipio().trim());
            }
            if (preenchido(origem.sgUf())) {
                endereco.setState(origem.sgUf().trim());
            }
            if (preenchido(origem.nrCep())) {
                endereco.setPostalCode(origem.nrCep().trim());
            }

            if (!endereco.isEmpty()) {
                paciente.addAddress(endereco);
            }
        }
    }

    private static String trim(String valor) {
        return valor == null ? null : valor.trim();
    }

    private static boolean preenchido(String valor) {
        return valor != null && !valor.trim().isEmpty();
    }
}

