/**
 * Trilha de auditoria de acesso a dado de paciente.
 *
 * <p>RNF-06 e a exigencia do DPO na ata de 14/07: "eu quero registrado quem
 * acessa o que".
 *
 * <p>O paciente e sempre identificado pelo identificador logico. CPF nunca entra
 * aqui — nem como criterio de busca registrado, nem como resultado.
 */
@Component
public class AuditoriaTrilha {

    private static final Logger trilha = LoggerFactory.getLogger("auditoria");

    public void registrarLeitura(String consumidor, String operacao, int cdPaciente) {
        trilha.info("consumidor={} operacao={} paciente={}", consumidor, operacao, cdPaciente);
    }

    /**
     * Registra uma busca pelos pacientes que ela devolveu.
     *
     * <p>O criterio NAO e registrado: se fosse, uma busca por CPF colocaria o
     * CPF na trilha, contrariando PD-04.
     */
    public void registrarBusca(String consumidor, String criterio, List<Integer> pacientes) {
        trilha.info("consumidor={} operacao=search criterio={} encontrados={} pacientes={}",
                consumidor, criterio, pacientes.size(), pacientes);
    }

    public void registrarRecusa(String consumidor, String motivo) {
        trilha.warn("consumidor={} operacao=recusada motivo={}", consumidor, motivo);
    }
}

