 * fachada nao implementa, ela nao promete no CapabilityStatement.
 */
@Component
public class PatientResourceProvider implements IResourceProvider {

    private final PacienteService servico;
    private final AuditoriaTrilha auditoria;
    private final int limiteMaximo;

    public PatientResourceProvider(PacienteService servico,
                                   AuditoriaTrilha auditoria,
                                   @Value("${fachada.busca.limite-maximo:50}") int limiteMaximo) {
        this.servico = servico;
        this.auditoria = auditoria;
        this.limiteMaximo = limiteMaximo;
    }

    @Override
    public Class<? extends IBaseResource> getResourceType() {
        return Patient.class;
    }

    @Read
    public Patient ler(@IdParam IdType id, RequestDetails requisicao) {
        int codigo;
        try {
            codigo = Integer.parseInt(id.getIdPart());
        } catch (NumberFormatException naoEhNumero) {
            throw new ResourceNotFoundException(id);
        }
        var paciente = servico.porCodigo(codigo)
                .orElseThrow(() -> new ResourceNotFoundException(id));
        auditoria.registrarLeitura(consumidor(requisicao), "read", codigo);
        return paciente;
    }

    /**
     * Busca por um criterio por vez.
     *
     * <p>Combinacao de criterios (nome + nascimento, por exemplo) nao faz parte
     * desta entrega e e recusada explicitamente, em vez de ser silenciosamente
     * ignorada — um filtro que o servidor descarta sem avisar devolve mais
     * paciente do que o cliente pediu, e em identificacao isso e perigoso.
     */
