    public IBundleProvider buscar(
            @OptionalParam(name = Patient.SP_RES_ID) TokenParam porCodigo,
            @OptionalParam(name = Patient.SP_IDENTIFIER) TokenParam porIdentificador,
            @OptionalParam(name = Patient.SP_NAME) StringParam porNome,
            @OptionalParam(name = Patient.SP_BIRTHDATE) DateParam porNascimento,
            @OptionalParam(name = Constants.PARAM_LASTUPDATED) DateRangeParam porAtualizacao,
            RequestDetails requisicao) {

        var informados = new ArrayList<String>();
        if (porCodigo != null) {
            informados.add(Patient.SP_RES_ID);
        }
        if (porIdentificador != null) {
            informados.add(Patient.SP_IDENTIFIER);
        }
        if (porNome != null) {
            informados.add(Patient.SP_NAME);
        }
        if (porNascimento != null) {
            informados.add(Patient.SP_BIRTHDATE);
        }
        if (porAtualizacao != null) {
            informados.add(Constants.PARAM_LASTUPDATED);
