import ca.uhn.fhir.interceptor.api.Interceptor;
import ca.uhn.fhir.interceptor.api.Pointcut;
import ca.uhn.fhir.rest.server.exceptions.InvalidRequestException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Locale;
import java.util.regex.Pattern;
import org.springframework.stereotype.Component;

/**
 * Faz valer PD-03 e PD-04 na porta de entrada.
 *
 * <p>PD-04 / RNF-05 — CPF nao pode aparecer em URL. Uma vez na cadeia de
 * consulta, o valor vaza para log de acesso, proxy e telemetria, e nao adianta
 * mais sanitizar dentro da aplicacao. Consulta por CPF so pelo
 * {@code POST [base]/Patient/_search}, com o valor no corpo.
 *
 * <p>PD-03 — nome da mae esta fora de escopo por decisao do DPO. Nao e apenas
 * omitido do retorno: nao e aceito nem como criterio.
 *
 * <p>Nenhuma das duas recusas ecoa o valor recebido, na resposta ou no log.
 */
@Interceptor
@Component
public class ProtecaoDeDadosInterceptor {

    /** CPF com ou sem mascara. A fronteira evita confundir com CNS (15 digitos). */
    private static final Pattern CPF_NA_URL = Pattern.compile(
            "(?<![0-9])(?:[0-9]{3}\\.[0-9]{3}\\.[0-9]{3}-[0-9]{2}|[0-9]{11})(?![0-9])");

    private static final Pattern PARAMETRO_DE_NOME_DA_MAE = Pattern.compile(
            "(?i)(^|[?&])(mothersmaidenname|mothers-maiden-name|mother|nm_mae|nomemae|nome-mae|mae)=");

    private final AuditoriaTrilha auditoria;

    public ProtecaoDeDadosInterceptor(AuditoriaTrilha auditoria) {
        this.auditoria = auditoria;
    }

    @Hook(Pointcut.SERVER_INCOMING_REQUEST_PRE_PROCESSED)
    public boolean verificar(HttpServletRequest requisicao, HttpServletResponse resposta) {
        var bruta = requisicao.getQueryString();
        if (bruta == null || bruta.isEmpty()) {
            return true;
        }
        var consulta = URLDecoder.decode(bruta, StandardCharsets.UTF_8);

        if (PARAMETRO_DE_NOME_DA_MAE.matcher(consulta).find()) {
            auditoria.registrarRecusa(consumidor(requisicao),
                    "nome-da-mae-fora-de-escopo");
            throw new InvalidRequestException(
                    "Nome da mae esta fora de escopo desta integracao (PD-03) e nao e aceito como criterio.");
        }

        boolean metodoExpoeNaUrl = !"POST".equalsIgnoreCase(requisicao.getMethod());
        boolean pareceCpf = CPF_NA_URL.matcher(consulta).find()
                || consulta.toLowerCase(Locale.ROOT).contains(Sistemas.CPF.toLowerCase(Locale.ROOT));

        if (metodoExpoeNaUrl && pareceCpf) {
            auditoria.registrarRecusa(consumidor(requisicao), "cpf-em-url");
            throw new InvalidRequestException(
                    "CPF nao pode trafegar em URL. Use POST [base]/Patient/_search com o criterio no corpo.");
        }
        return true;
    }

    private static String consumidor(HttpServletRequest requisicao) {
        var identificado = requisicao.getHeader("X-Consumidor");
        return identificado == null || identificado.isBlank() ? "anonimo" : identificado;
    }
}

