package br.com.vitaflow.fhirfacade.origem;

import java.util.ArrayList;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

/**
 * RA-04: a integracao deve funcionar sem privilegio administrativo — apenas
 * SELECT no schema sigh.
 *
 * <p>Isso e verificado na partida, e nao confiado a configuracao. Um usuario com
 * privilegio a mais nao e um detalhe operacional: e a diferenca entre uma
 * fachada que nao pode escrever e uma que apenas nao escreve hoje. Se houver
 * privilegio sobrando, a aplicacao nao sobe.
 */
@Component
public class PrivilegioDeLeituraVerificador {

    private static final Logger log = LoggerFactory.getLogger(PrivilegioDeLeituraVerificador.class);

    private final JdbcTemplate jdbc;

    public PrivilegioDeLeituraVerificador(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @EventListener(ApplicationReadyEvent.class)
    public void verificarNaPartida() {
        var excessos = privilegiosDeEscrita();
        if (!excessos.isEmpty()) {
            throw new IllegalStateException(
                    "A conexao com o SIGH tem privilegio alem de SELECT, o que viola RA-04: "
                            + excessos + ". Use um usuario somente leitura (integracao_ro).");
        }
        log.info("Privilegio da conexao conferido: somente leitura no schema sigh (RA-04).");
    }

    /** Devolve os privilegios de escrita encontrados. Vazio e o esperado. */
    public java.util.List<String> privilegiosDeEscrita() {
        var achados = new ArrayList<String>();
        // Sintaxe suportada desde muito antes do PostgreSQL 12.
        var linha = jdbc.queryForMap("""
                SELECT has_database_privilege(current_database(), 'CREATE') AS cria_banco,
                       has_schema_privilege('sigh', 'CREATE')                AS cria_schema,
                       has_table_privilege('sigh.paciente', 'INSERT')        AS insere,
                       has_table_privilege('sigh.paciente', 'UPDATE')        AS atualiza,
                       has_table_privilege('sigh.paciente', 'DELETE')        AS remove,
                       has_table_privilege('sigh.paciente', 'TRUNCATE')      AS trunca
                """);
        linha.forEach((privilegio, concedido) -> {
            if (Boolean.TRUE.equals(concedido)) {
                achados.add(privilegio);
            }
        });
        return achados;
    }
}

