                    contatos, List.of());
        }

        @Test
        @DisplayName("os quatro valores de tp_contato produzem a combinacao correta")
        void quatroTiposDeContato() {
            var paciente = comContatos(List.of(
                    new ContatoRegistro(1, 10001, "CEL", "71924465777", "N"),
                    new ContatoRegistro(2, 10001, "RES", "7131198500", "N"),
                    new ContatoRegistro(3, 10001, "COM", "7122081233", "N"),
                    new ContatoRegistro(4, 10001, "EML", "adriana.82@exemplo.com.br", "N")));

            assertThat(paciente.getTelecom()).hasSize(4);
            assertThat(paciente.getTelecom().get(0).getSystem()).isEqualTo(ContactPoint.ContactPointSystem.PHONE);
            assertThat(paciente.getTelecom().get(0).getUse()).isEqualTo(ContactPoint.ContactPointUse.MOBILE);
            assertThat(paciente.getTelecom().get(1).getUse()).isEqualTo(ContactPoint.ContactPointUse.HOME);
            assertThat(paciente.getTelecom().get(2).getUse()).isEqualTo(ContactPoint.ContactPointUse.WORK);
            assertThat(paciente.getTelecom().get(3).getSystem()).isEqualTo(ContactPoint.ContactPointSystem.EMAIL);
            assertThat(paciente.getTelecom().get(3).getUse()).isNull();
        }

        @Test
        @DisplayName("Scenario: celular com prefixo de pais vira E.164")
        void celularComPrefixo() {
            var paciente = comContatos(List.of(
                    new ContatoRegistro(1, 10001, "CEL", "+55 71 924465777", "S")));

            var ponto = paciente.getTelecomFirstRep();
            assertThat(ponto.getSystem()).isEqualTo(ContactPoint.ContactPointSystem.PHONE);
            assertThat(ponto.getUse()).isEqualTo(ContactPoint.ContactPointUse.MOBILE);
            assertThat(ponto.getValue()).isEqualTo("+5571924465777");
        }

        @Test
        @DisplayName("telefone que nao da para normalizar sai como veio, sem prefixo inventado")
        void telefoneNaoInferivel() {
            var paciente = comContatos(List.of(
                    new ContatoRegistro(1, 10001, "CEL", "ramal 4021", "N")));

            assertThat(paciente.getTelecomFirstRep().getValue()).isEqualTo("ramal 4021");
        }

        @Test
        @DisplayName("Scenario: paciente sem nenhum contato")
        void semContato() {
            var paciente = comContatos(List.of());
            assertThat(paciente.hasTelecom()).isFalse();
        }

        @Test
        @DisplayName("Scenario: mais de um contato principal — ambos recebem rank 1, nenhum e descartado")
        void doisPrincipais() {
            var paciente = comContatos(List.of(
                    new ContatoRegistro(1, 10001, "CEL", "71924465777", "S"),
                    new ContatoRegistro(2, 10001, "RES", "7131198500", "S")));

            assertThat(paciente.getTelecom()).hasSize(2);
            assertThat(paciente.getTelecom()).allMatch(c -> c.getRank() == 1);
        }

        @Test
        @DisplayName("sem contato principal, nenhum rank e emitido")
        void nenhumPrincipal() {
            var paciente = comContatos(List.of(
                    new ContatoRegistro(1, 10001, "CEL", "71924465777", "N")));

            assertThat(paciente.getTelecomFirstRep().hasRank()).isFalse();
        }

        @Test
        @DisplayName("tipo de contato desconhecido e preservado em vez de sumir")
        void tipoDesconhecido() {
            var paciente = comContatos(List.of(
                    new ContatoRegistro(1, 10001, "FAX", "7131198500", "N")));

            assertThat(paciente.getTelecomFirstRep().getSystem())
                    .isEqualTo(ContactPoint.ContactPointSystem.OTHER);
            assertThat(paciente.getTelecomFirstRep().getValue()).isEqualTo("7131198500");
        }

        @Test
        @DisplayName("contato com conteudo vazio e ignorado")
        void contatoVazio() {
            var paciente = comContatos(List.of(new ContatoRegistro(1, 10001, "CEL", "  ", "N")));
            assertThat(paciente.hasTelecom()).isFalse();
        }
    }

    // ------------------------------------------------------------- enderecos

    @Nested
    @DisplayName("Requirement: Endereco do paciente")
    class Enderecos {

        private Patient comEnderecos(List<EnderecoRegistro> enderecos) {
            return mapeador.paraPatient(
                    registro(10001, "Luciana", null, "F", null, null, "S",
                            LocalDate.of(1940, 8, 4), null),
                    List.of(), enderecos);
        }

        @Test
        @DisplayName("endereco completo")
        void enderecoCompleto() {
            var paciente = comEnderecos(List.of(new EnderecoRegistro(
                    1, 10001, "Rua das Flores", "123", "Apto 4", "Boa Viagem",
                    2611606, "Recife", "PE", "51020000", "S")));

            var endereco = paciente.getAddressFirstRep();
            assertThat(endereco.getLine()).extracting(l -> l.getValue())
                    .containsExactly("Rua das Flores, 123", "Apto 4");
            assertThat(endereco.getDistrict()).isEqualTo("Boa Viagem");
            assertThat(endereco.getCity()).isEqualTo("Recife");
            assertThat(endereco.getState()).isEqualTo("PE");
            assertThat(endereco.getPostalCode()).isEqualTo("51020000");
        }

        @Test
        @DisplayName("Scenario: endereco sem CEP — 15,6% dos enderecos da base")
        void semCep() {
            var paciente = comEnderecos(List.of(new EnderecoRegistro(
                    1, 10001, "Rua das Flores", "123", null, "Boa Viagem",
                    2611606, "Recife", "PE", null, "S")));

            var endereco = paciente.getAddressFirstRep();
            assertThat(endereco.hasPostalCode()).isFalse();
            assertThat(endereco.getCity()).isEqualTo("Recife");
            assertThat(endereco.getState()).isEqualTo("PE");
        }

        @Test
        @DisplayName("Scenario: municipio fora da tabela de referencia — some so a cidade")
        void municipioSemCorrespondencia() {
            var paciente = comEnderecos(List.of(new EnderecoRegistro(
                    1, 10001, "Rua das Flores", "123", null, "Centro",
                    9999999, null, "PE", "51020000", "S")));

            var endereco = paciente.getAddressFirstRep();
            assertThat(endereco.hasCity()).isFalse();
            assertThat(endereco.getState()).isEqualTo("PE");
            assertThat(endereco.getPostalCode()).isEqualTo("51020000");
        }

        @Test
        @DisplayName("Scenario: paciente sem endereco")
        void semEndereco() {
            assertThat(comEnderecos(List.of()).hasAddress()).isFalse();
        }

        @Test
        @DisplayName("endereco principal vem primeiro — Address nao tem rank")
        void principalPrimeiro() {
            var paciente = comEnderecos(List.of(
                    new EnderecoRegistro(1, 10001, "Rua Secundaria", null, null, null,
                            null, null, "PE", null, "N"),
                    new EnderecoRegistro(2, 10001, "Rua Principal", null, null, null,
                            null, null, "PE", null, "S")));

            assertThat(paciente.getAddress().get(0).getLine().get(0).getValue()).isEqualTo("Rua Principal");
        }

        @Test
        @DisplayName("numero em texto, como 'S/N', e preservado")
        void numeroEmTexto() {
            var paciente = comEnderecos(List.of(new EnderecoRegistro(
                    1, 10001, "Rodovia BR-101", "S/N", null, null, null, null, "PE", null, "S")));

            assertThat(paciente.getAddressFirstRep().getLine().get(0).getValue())
                    .isEqualTo("Rodovia BR-101, S/N");
        }

        @Test
        @DisplayName("endereco totalmente vazio nao entra no recurso")
        void enderecoVazio() {
            var paciente = comEnderecos(List.of(new EnderecoRegistro(
                    1, 10001, null, null, null, null, null, null, null, null, "N")));

            assertThat(paciente.hasAddress()).isFalse();
        }
    }

    // ------------------------------------------------------------------ meta

    @Test
    @DisplayName("meta.lastUpdated vem do mesmo COALESCE que filtra a janela incremental")
    void metaLastUpdated() {
        var paciente = mapear(registro(10002, "Pedro", null, "M", null, null, "S",
                LocalDate.of(2000, 7, 23), null));

        assertThat(paciente.getMeta().getLastUpdated()).isNotNull();
    }

    @Test
    @DisplayName("registro sem nenhum carimbo temporal nao inventa meta.lastUpdated")
    void semCarimbo() {
        var semCarimbo = new PacienteRegistro(10003, "Jose", null, LocalDate.of(1950, 4, 6),
                "M", null, null, "S", null, null);

        assertThat(mapear(semCarimbo).getMeta().getLastUpdated()).isNull();
    }
}

