package br.com.vitaflow.fhirfacade.traducao;

import static org.assertj.core.api.Assertions.assertThat;

import br.com.vitaflow.fhirfacade.origem.ContatoRegistro;
import br.com.vitaflow.fhirfacade.origem.EnderecoRegistro;
import br.com.vitaflow.fhirfacade.origem.PacienteRegistro;
import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.LoggerContext;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;
import org.hl7.fhir.r4.model.ContactPoint;
import org.hl7.fhir.r4.model.DateTimeType;
import org.hl7.fhir.r4.model.Enumerations.AdministrativeGender;
import org.hl7.fhir.r4.model.HumanName;
import org.hl7.fhir.r4.model.Patient;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.slf4j.LoggerFactory;

/**
 * Cada teste daqui corresponde a um cenario da spec fhir/paciente.
 *
 * <p>Os registros usados espelham pacientes reais da base de homologacao, pelos
 * mesmos codigos: cada um e a prova viva de uma divergencia registrada.
 */
@DisplayName("Traducao de paciente do SIGH para Patient R4")
class PacienteMapperTest {

    private final PacienteMapper mapeador = new PacienteMapper();
    private ListAppender<ILoggingEvent> logCapturado;

    @BeforeEach
    void capturarLog() {
        var logger = (ch.qos.logback.classic.Logger)
                LoggerFactory.getLogger(PacienteMapper.class);
        logCapturado = new ListAppender<>();
        logCapturado.setContext((LoggerContext) LoggerFactory.getILoggerFactory());
        logCapturado.start();
        logger.addAppender(logCapturado);
        logger.setLevel(Level.DEBUG);
    }

    @AfterEach
    void soltarLog() {
        ((ch.qos.logback.classic.Logger) LoggerFactory.getLogger(PacienteMapper.class))
                .detachAppender(logCapturado);
    }

    // ---------------------------------------------------------------- helpers

    private static PacienteRegistro registro(int codigo, String nome, String social, String sexo,
                                             String cpf, String cns, String ativo,
                                             LocalDate nascimento, LocalDate obito) {
        return new PacienteRegistro(codigo, nome, social, nascimento, sexo, cpf, cns, ativo, obito,
                LocalDateTime.of(2026, 5, 8, 15, 34));
    }

    private Patient mapear(PacienteRegistro registro) {
        return mapeador.paraPatient(registro, List.of(), List.of());
    }

    // ------------------------------------------------------- identificadores

    @Nested
    @DisplayName("Requirement: Identificador logico do recurso")
    class IdentificadorLogico {

        @Test
        @DisplayName("Scenario: paciente com todos os documentos preenchidos")
        void pacienteCompleto() {
            var paciente = mapear(registro(10001, "Luciana Almeida Nascimento", null, "F",
                    "26716608044", "205795840320002", "S",
                    LocalDate.of(1940, 8, 4), null));

            assertThat(paciente.getIdElement().getIdPart()).isEqualTo("10001");
            assertThat(paciente.getIdentifier())
                    .extracting(i -> i.getSystem() + "|" + i.getValue())
                    .containsExactlyInAnyOrder(
                            Sistemas.CD_PACIENTE + "|10001",
                            Sistemas.CPF + "|26716608044",
                            Sistemas.CNS + "|205795840320002");
        }

        @Test
        @DisplayName("Scenario: paciente sem CPF continua tendo id — a ata dizia que nao existiria")
        void pacienteSemCpf() {
            var paciente = mapear(registro(10004, "Felipe Barbosa Ferreira", null, "M",
                    null, "190777220470008", "S", LocalDate.of(2016, 4, 20), null));

            assertThat(paciente.getIdElement().getIdPart()).isEqualTo("10004");
            assertThat(paciente.getIdentifier())
                    .noneMatch(i -> Sistemas.CPF.equals(i.getSystem()));
        }
    }

    @Nested
    @DisplayName("Requirement: Identificadores de negocio opcionais")
    class IdentificadoresOpcionais {

        @Test
        @DisplayName("Scenario: paciente sem CNS nao ganha entrada vazia")
        void semCns() {
            var paciente = mapear(registro(10014, "Ricardo Nunes Santos", null, "M",
                    "43001074329", null, "S", LocalDate.of(1969, 8, 21), null));

            assertThat(paciente.getIdentifier())
                    .noneMatch(i -> Sistemas.CNS.equals(i.getSystem()))
                    .allMatch(i -> i.getValue() != null && !i.getValue().isBlank());
        }

        @Test
        @DisplayName("cadeia vazia na origem nao vira identificador")
        void cadeiaVaziaNaoViraIdentificador() {
            var paciente = mapear(registro(10099, "Teste", null, "M", "   ", "", "S",
                    LocalDate.of(1980, 1, 1), null));

            assertThat(paciente.getIdentifier()).hasSize(1);
            assertThat(paciente.getIdentifierFirstRep().getSystem()).isEqualTo(Sistemas.CD_PACIENTE);
        }
    }

    @Nested
    @DisplayName("Requirement: Paciente sem identificador de negocio e retornavel")
    class SemDocumentoAlgum {

        @Test
        @DisplayName("Scenario: leitura de paciente sem CPF e sem CNS")
        void semCpfESemCns() {
            var paciente = mapear(registro(10023, "Paulo Silva Ribeiro", null, "M",
                    null, null, "S", LocalDate.of(1947, 7, 28), null));

            assertThat(paciente.getIdentifier()).hasSize(1);
            assertThat(paciente.getIdentifierFirstRep().getSystem()).isEqualTo(Sistemas.CD_PACIENTE);
            assertThat(paciente.getIdentifierFirstRep().getValue()).isEqualTo("10023");
        }
    }

    // ------------------------------------------------------------------ nomes

    @Nested
    @DisplayName("Requirement: Precedencia de exibicao do nome social")
    class NomeSocial {

        @Test
        @DisplayName("Scenario: paciente com nome social")
        void comNomeSocial() {
            var paciente = mapear(registro(10011, "Anderson Silva Rocha", "Juliana Silva Rocha",
                    "M", "32612087087", "218620781540003", "S", LocalDate.of(1989, 9, 14), null));

            assertThat(paciente.getName()).hasSize(2);
            assertThat(paciente.getName().get(0).getUse()).isEqualTo(HumanName.NameUse.USUAL);
            assertThat(paciente.getName().get(0).getText()).isEqualTo("Juliana Silva Rocha");
            assertThat(paciente.getName().get(1).getUse()).isEqualTo(HumanName.NameUse.OFFICIAL);
            assertThat(paciente.getName().get(1).getText()).isEqualTo("Anderson Silva Rocha");
        }

        @Test
        @DisplayName("Scenario: paciente sem nome social")
        void semNomeSocial() {
            var paciente = mapear(registro(10001, "Luciana Almeida Nascimento", null, "F",
                    "26716608044", "205795840320002", "S", LocalDate.of(1940, 8, 4), null));

            assertThat(paciente.getName()).hasSize(1);
            assertThat(paciente.getNameFirstRep().getUse()).isEqualTo(HumanName.NameUse.OFFICIAL);
            assertThat(paciente.getName()).noneMatch(n -> n.getUse() == HumanName.NameUse.USUAL);
        }

        @Test
        @DisplayName("nome social em branco nao gera entrada usual")
        void nomeSocialEmBranco() {
            var paciente = mapear(registro(10001, "Luciana Almeida Nascimento", "   ", "F",
                    null, null, "S", LocalDate.of(1940, 8, 4), null));

            assertThat(paciente.getName()).hasSize(1);
        }
    }

    // ------------------------------------------------------------------ sexo

    @Nested
    @DisplayName("Requirement: Mapeamento de sexo administrativo")
    class Sexo {

        @Test
        @DisplayName("Scenario: sexo indeterminado na origem — 'I' vira unknown, nunca other")
        void sexoI() {
            var paciente = mapear(registro(10044, "Sergio Dias Tavares", null, "I",
                    "11111111111", null, "S", LocalDate.of(1965, 7, 5), null));

            assertThat(paciente.getGender()).isEqualTo(AdministrativeGender.UNKNOWN);
            assertThat(paciente.getGender()).isNotEqualTo(AdministrativeGender.OTHER);

            var extensao = paciente.getGenderElement().getExtensionByUrl(Sistemas.EXT_TP_SEXO_ORIGEM);
            assertThat(extensao).isNotNull();
            assertThat(extensao.getValue().primitiveValue()).isEqualTo("I");
        }

        @Test
        @DisplayName("Scenario: sexo ausente — unknown, sem afirmar um codigo inexistente")
        void sexoNulo() {
            var paciente = mapear(registro(10099, "Teste", null, null,
                    null, null, "S", LocalDate.of(1980, 1, 1), null));

            assertThat(paciente.getGender()).isEqualTo(AdministrativeGender.UNKNOWN);
            assertThat(paciente.getGenderElement().getExtensionByUrl(Sistemas.EXT_TP_SEXO_ORIGEM)).isNull();
        }

        @Test
        @DisplayName("M e F traduzem direto e nao geram extensao")
        void masculinoEFeminino() {
            var homem = mapear(registro(1, "A", null, "M", null, null, "S", LocalDate.of(1980, 1, 1), null));
            var mulher = mapear(registro(2, "B", null, "F", null, null, "S", LocalDate.of(1980, 1, 1), null));

            assertThat(homem.getGender()).isEqualTo(AdministrativeGender.MALE);
            assertThat(mulher.getGender()).isEqualTo(AdministrativeGender.FEMALE);
            assertThat(homem.getGenderElement().getExtensionByUrl(Sistemas.EXT_TP_SEXO_ORIGEM)).isNull();
            assertThat(mulher.getGenderElement().getExtensionByUrl(Sistemas.EXT_TP_SEXO_ORIGEM)).isNull();
        }

        @Test
        @DisplayName("valor novo que a Medsys venha a criar cai em unknown, preservado na extensao")
        void valorDesconhecidoFalhaDeFormaSegura() {
            var paciente = mapear(registro(3, "C", null, "X", null, null, "S", LocalDate.of(1980, 1, 1), null));

            assertThat(paciente.getGender()).isEqualTo(AdministrativeGender.UNKNOWN);
            assertThat(paciente.getGenderElement()
                    .getExtensionByUrl(Sistemas.EXT_TP_SEXO_ORIGEM).getValue().primitiveValue())
                    .isEqualTo("X");
        }
    }

    // ------------------------------------------------------- situacao e obito

    @Nested
    @DisplayName("Requirement: Situacao cadastral e obito sao independentes")
    class SituacaoEObito {

        @Test
        @DisplayName("Scenario: paciente inativo e vivo — 9 dos 15 inativos da base")
        void inativoEVivo() {
            var paciente = mapear(registro(10012, "Thiago Soares Barbosa", null, "M",
                    null, "115216132000006", "N", LocalDate.of(1937, 9, 21), null));

            assertThat(paciente.getActive()).isFalse();
            assertThat(paciente.hasDeceased()).isFalse();
        }

        @Test
        @DisplayName("Scenario: paciente falecido — active reflete st_ativo, nao o obito")
        void falecido() {
            var paciente = mapear(registro(10028, "Ana Silva Dias", null, "F",
                    null, null, "N", LocalDate.of(1935, 9, 13), LocalDate.of(2024, 1, 20)));

            assertThat(paciente.getActive()).isFalse();
            assertThat(paciente.hasDeceasedDateTimeType()).isTrue();
            assertThat(((DateTimeType) paciente.getDeceased()).getValueAsString()).isEqualTo("2024-01-20");
        }

        @Test
        @DisplayName("um paciente ativo com obito registrado mantem active=true")
        void ativoComObitoNaoColapsa() {
            var paciente = mapear(registro(999, "Caso limite", null, "F",
                    null, null, "S", LocalDate.of(1950, 1, 1), LocalDate.of(2025, 1, 1)));

            assertThat(paciente.getActive()).isTrue();
            assertThat(paciente.hasDeceasedDateTimeType()).isTrue();
        }

        @Test
        @DisplayName("st_ativo nulo nao vira active — a fachada nao chuta situacao cadastral")
        void situacaoNulaNaoEhAfirmada() {
            var paciente = mapear(registro(998, "Sem situacao", null, "F",
                    null, null, null, LocalDate.of(1950, 1, 1), null));

            assertThat(paciente.hasActive()).isFalse();
        }
    }

    @Nested
    @DisplayName("Requirement: Tratamento de datas incoerentes na origem")
    class DatasIncoerentes {

        @Test
        @DisplayName("Scenario: obito anterior ao nascimento — deceased omitido e registro tecnico sem dado pessoal")
        void obitoAnteriorAoNascimento() {
            var paciente = mapear(registro(10074, "Mariana Tavares Melo", null, "F",
                    null, null, "S", LocalDate.of(2023, 8, 3), LocalDate.of(2019, 1, 21)));

            assertThat(paciente.hasDeceased()).isFalse();

            var mensagens = logCapturado.list.stream().map(ILoggingEvent::getFormattedMessage).toList();
            assertThat(mensagens).anyMatch(m -> m.contains("10074"));
            assertThat(mensagens)
                    .noneMatch(m -> m.contains("Mariana Tavares Melo"))
                    .noneMatch(m -> m.contains("2019-01-21"))
                    .noneMatch(m -> m.contains("2023-08-03"));
        }

        @Test
        @DisplayName("sem data de nascimento nao ha como comparar; o obito e mantido")
        void semNascimentoMantemObito() {
            var paciente = mapear(registro(997, "Sem nascimento", null, "F",
                    null, null, "S", null, LocalDate.of(2020, 1, 1)));

            assertThat(paciente.hasDeceasedDateTimeType()).isTrue();
        }
    }

    @Nested
    @DisplayName("Requirement: Busca por data de nascimento (tolerancia a nulo)")
    class Nascimento {

        @Test
        @DisplayName("Scenario: paciente sem data de nascimento — elemento omitido")
        void semNascimento() {
            var paciente = mapear(registro(996, "Sem nascimento", null, "F",
                    null, null, "S", null, null));

            assertThat(paciente.hasBirthDate()).isFalse();
        }

        @Test
        void comNascimento() {
            var paciente = mapear(registro(10001, "Luciana", null, "F", null, null, "S",
                    LocalDate.of(1940, 8, 4), null));

            assertThat(paciente.getBirthDateElement().getValueAsString()).isEqualTo("1940-08-04");
        }
    }

    // ------------------------------------------------------------- contatos

    @Nested
    @DisplayName("Requirement: Contatos telefonicos e eletronicos")
    class Contatos {

        private Patient comContatos(List<ContatoRegistro> contatos) {
            return mapeador.paraPatient(
                    registro(10001, "Luciana", null, "F", null, null, "S",
                            LocalDate.of(1940, 8, 4), null),
                    contatos, List.of());
        }

        @Test
        @DisplayName("os quatro valores de tp_contato produzem a combinacao correta")
        void quatroTiposDeContato() {
            var paciente = comContatos(List.of(
                    new ContatoRegistro(1, 10001, "CEL", "71924465777", "N"),
                    new ContatoRegistro(2, 10001, "RES", "7131198500", "N"),
                    new ContatoRegistro(3, 10001, "COM", "7122081233", "N"),
                    new ContatoRegistro(4, 10001, "EML", "adriana.82@exemplo.com.br", "N")));

            assertThat(paciente.getTelecom()).hasSize(4);
            assertThat(paciente.getTelecom().get(0).getSystem()).isEqualTo(ContactPoint.ContactPointSystem.PHONE);
            assertThat(paciente.getTelecom().get(0).getUse()).isEqualTo(ContactPoint.ContactPointUse.MOBILE);
            assertThat(paciente.getTelecom().get(1).getUse()).isEqualTo(ContactPoint.ContactPointUse.HOME);
            assertThat(paciente.getTelecom().get(2).getUse()).isEqualTo(ContactPoint.ContactPointUse.WORK);
            assertThat(paciente.getTelecom().get(3).getSystem()).isEqualTo(ContactPoint.ContactPointSystem.EMAIL);
            assertThat(paciente.getTelecom().get(3).getUse()).isNull();
        }

        @Test
        @DisplayName("Scenario: celular com prefixo de pais vira E.164")
        void celularComPrefixo() {
            var paciente = comContatos(List.of(
                    new ContatoRegistro(1, 10001, "CEL", "+55 71 924465777", "S")));

