package br.com.vitaflow.fhirfacade.apoio;

import java.io.File;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.utility.DockerImageName;
import org.testcontainers.utility.MountableFile;

/**
 * Base de homologacao do SIGH em conteiner.
 *
 * <p>Sobe o DDL e a carga que o hospital entregou, sem copia nem adaptacao: os
 * testes rodam contra o mesmo schema do fornecedor que a producao usa. Adaptar
 * o schema para o teste passar seria testar outra coisa.
 */
public final class SighPostgres {

    /** Mesma imagem do compose de homologacao. */
    public static final String IMAGEM_HOMOLOGACAO = "postgres:17-alpine";

    /**
     * Versao de producao. O documento de arquitetura avisa: homologacao roda 17,
     * producao roda 12.14, e recurso posterior ao 12 nao pode ser usado.
     */
    public static final String IMAGEM_PRODUCAO = "postgres:12.14-alpine";

    private static PostgreSQLContainer<?> homologacao;

    public static synchronized PostgreSQLContainer<?> homologacao() {
        if (homologacao == null) {
            homologacao = criar(IMAGEM_HOMOLOGACAO);
            homologacao.start();
        }
        return homologacao;
    }

    public static PostgreSQLContainer<?> criar(String imagem) {
        return new PostgreSQLContainer<>(DockerImageName.parse(imagem)
                .asCompatibleSubstituteFor("postgres"))
                .withDatabaseName("sigh")
                .withUsername("sigh_app")
                .withPassword("sigh_app")
                .withCopyFileToContainer(migracao("V1__schema.sql"),
                        "/docker-entrypoint-initdb.d/V1__schema.sql")
                .withCopyFileToContainer(migracao("V2__seed.sql"),
                        "/docker-entrypoint-initdb.d/V2__seed.sql");
    }

    private static MountableFile migracao(String arquivo) {
        var caminho = new File("../legacy-db/migrations/" + arquivo).getAbsoluteFile();
        if (!caminho.exists()) {
            throw new IllegalStateException("Migracao do SIGH nao encontrada: " + caminho);
        }
        return MountableFile.forHostPath(caminho.toPath());
    }

    private SighPostgres() {
    }
}

