package br.com.vitaflow.fhirfacade.origem;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import br.com.vitaflow.fhirfacade.apoio.SighPostgres;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;

/**
 * RA-01 e RA-04: somente leitura, sem privilegio administrativo.
 *
 * <p>Estes testes nao verificam que a fachada evita escrever. Verificam que ela
 * NAO CONSEGUE escrever, o que e outra coisa.
 */
@DisplayName("Acesso a origem: somente leitura, garantido pelo banco")
class AcessoSomenteLeituraIT {

    private Connection conectarComoIntegracao() throws SQLException {
        var container = SighPostgres.homologacao();
        return DriverManager.getConnection(container.getJdbcUrl(), "integracao_ro", "integracao_ro");
    }

    @ParameterizedTest(name = "o banco recusa: {0}")
    @ValueSource(strings = {
            "INSERT INTO sigh.paciente (cd_paciente, nm_paciente) VALUES (999999, 'Invasor')",
            "UPDATE sigh.paciente SET nm_paciente = 'Alterado' WHERE cd_paciente = 10001",
            "DELETE FROM sigh.paciente WHERE cd_paciente = 10001",
            "CREATE EXTENSION unaccent",
            "CREATE INDEX ix_teste ON sigh.paciente (nm_paciente)",
            "DROP TABLE sigh.paciente"
    })
    @DisplayName("nenhuma escrita passa pelo usuario integracao_ro")
    void bancoRecusaEscrita(String comando) throws SQLException {
        try (var conexao = conectarComoIntegracao(); var statement = conexao.createStatement()) {
            assertThatThrownBy(() -> statement.execute(comando))
                    .isInstanceOf(SQLException.class)
                    .hasMessageContaining("permiss");
        }
    }

    @Test
    @DisplayName("o SELECT que a fachada precisa continua funcionando")
    void leituraFunciona() throws SQLException {
        try (var conexao = conectarComoIntegracao();
             var statement = conexao.createStatement();
             var resultado = statement.executeQuery("SELECT count(*) FROM sigh.paciente")) {
            assertThat(resultado.next()).isTrue();
            assertThat(resultado.getInt(1)).isEqualTo(200);
        }
    }

    @Test
    @DisplayName("a verificacao de partida aprova o usuario somente leitura")
    void verificacaoAprovaIntegracaoRo() {
        var verificador = new PrivilegioDeLeituraVerificador(jdbcCom("integracao_ro", "integracao_ro"));

        assertThat(verificador.privilegiosDeEscrita()).isEmpty();
        verificador.verificarNaPartida();
    }

    @Test
    @DisplayName("a aplicacao NAO sobe com um usuario privilegiado — RA-04 nao e confiado a configuracao")
    void verificacaoReprovaUsuarioPrivilegiado() {
        var verificador = new PrivilegioDeLeituraVerificador(jdbcCom("sigh_app", "sigh_app"));

        assertThat(verificador.privilegiosDeEscrita()).isNotEmpty();
        assertThatThrownBy(verificador::verificarNaPartida)
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("RA-04")
                .hasMessageContaining("integracao_ro");
    }

    private static JdbcTemplate jdbcCom(String usuario, String senha) {
        var fonte = new DriverManagerDataSource(SighPostgres.homologacao().getJdbcUrl(), usuario, senha);
        fonte.setDriverClassName("org.postgresql.Driver");
        return new JdbcTemplate(fonte);
    }
}

