    @DisplayName("COALESCE recupera os 14 pacientes sem dt_atualizacao — sem ele ficariam invisiveis para sempre")
    void janelaIncrementalRecuperaSemCarimbo() {
        // Paciente 10179: dt_atualizacao nula, dt_cadastro em 09/08/2025.
        var janela = repositorio.alteradosNaJanela(
                LocalDateTime.of(2025, 8, 1, 0, 0),
                LocalDateTime.of(2025, 8, 31, 23, 59),
                500);

        assertThat(janela).extracting(PacienteRegistro::cdPaciente).contains(10179);
        assertThat(janela)
                .filteredOn(r -> r.cdPaciente() == 10179)
                .allMatch(r -> r.ultimaAtualizacao().toLocalDate().equals(LocalDate.of(2025, 8, 9)));
    }

    @Test
    @DisplayName("todo paciente tem carimbo de referencia, mesmo sem dt_atualizacao")
    void todosTemCarimbo() {
        var todos = repositorio.alteradosNaJanela(null, null, 1000);

        assertThat(todos).hasSize(200);
        assertThat(todos).allMatch(r -> r.ultimaAtualizacao() != null);
    }

    @Test
    @DisplayName("contatos do paciente")
    void contatos() {
        assertThat(repositorio.contatosDe(10001)).isNotEmpty();
    }

    @Test
    @DisplayName("enderecos com municipio resolvido por LEFT JOIN")
    void enderecos() {
        var comEndereco = repositorio.alteradosNaJanela(null, null, 1000).stream()
                .map(r -> repositorio.enderecosDe(r.cdPaciente()))
                .filter(e -> !e.isEmpty())
                .findFirst()
                .orElseThrow();

        assertThat(comEndereco).allMatch(e -> e.nmMunicipio() != null);
    }
}

