package br.com.vitaflow.fhirfacade.cache;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Supplier;
import org.hl7.fhir.r4.model.Patient;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/**
 * Cache em memoria, por Patient.id, com TTL curto.
 *
 * <p>RA-03 permite cache em memoria com tempo de vida curto e proibe base
 * espelhada. Por isso: ConcurrentHashMap em processo, sem serializacao, sem
 * disco, sem rede. Nada aqui sobrevive ao processo.
 *
 * <p>TTL padrao de 5 segundos, espelhando a defasagem tipica da replicacao por
 * streaming: um cache mais curto nao melhoraria a atualidade real do dado.
 */
@Component
public class PacienteCache {

    private record Entrada(Patient paciente, Instant expiraEm) {
    }

    private final Map<Integer, Entrada> entradas = new ConcurrentHashMap<>();
    private final Duration ttl;
    private final Clock relogio;

    public PacienteCache(@Value("${fachada.cache.ttl:PT5S}") Duration ttl) {
        this(ttl, Clock.systemUTC());
    }

    PacienteCache(Duration ttl, Clock relogio) {
        this.ttl = ttl;
        this.relogio = relogio;
    }

    public Optional<Patient> obter(int cdPaciente, Supplier<Optional<Patient>> origem) {
        var agora = relogio.instant();
        var entrada = entradas.get(cdPaciente);
        if (entrada != null && entrada.expiraEm().isAfter(agora)) {
            return Optional.of(entrada.paciente());
        }
        var recuperado = origem.get();
        recuperado.ifPresent(p -> entradas.put(cdPaciente, new Entrada(p, agora.plus(ttl))));
        return recuperado;
    }

    public void limpar() {
        entradas.clear();
    }

    public int tamanho() {
        return entradas.size();
    }
}

