package br.com.vitaflow.fhirfacade.origem;

import static org.assertj.core.api.Assertions.assertThat;

import br.com.vitaflow.fhirfacade.apoio.BaseIntegracao;
import java.time.LocalDate;
import java.time.LocalDateTime;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.NONE)
@DisplayName("Leitura do cadastro do SIGH")
class PacienteRepositoryIT extends BaseIntegracao {

    @Autowired
    PacienteRepository repositorio;

    @Test
    @DisplayName("le um paciente pelo codigo interno")
    void porCodigo() {
        var paciente = repositorio.porCodigo(10001).orElseThrow();

        assertThat(paciente.nmPaciente()).isEqualTo("Luciana Almeida Nascimento");
        assertThat(paciente.nrCpf()).isEqualTo("26716608044");
        assertThat(paciente.tpSexo()).isEqualTo("F");
    }

    @Test
    @DisplayName("codigo inexistente devolve vazio, nao excecao")
    void codigoInexistente() {
        assertThat(repositorio.porCodigo(999999)).isEmpty();
    }

    @Test
    @DisplayName("os 31 pacientes sem CPF sao lidos normalmente")
    void pacientesSemCpf() {
        var semCpf = repositorio.porCodigo(10004).orElseThrow();

        assertThat(semCpf.nrCpf()).isNull();
        assertThat(semCpf.nrCns()).isEqualTo("190777220470008");
    }

    @Test
    @DisplayName("os 7 pacientes sem CPF e sem CNS sao lidos normalmente")
    void pacientesSemDocumentoAlgum() {
        var semNada = repositorio.porCodigo(10023).orElseThrow();

        assertThat(semNada.nrCpf()).isNull();
        assertThat(semNada.nrCns()).isNull();
        assertThat(semNada.nmPaciente()).isEqualTo("Paulo Silva Ribeiro");
    }

    @Test
    @DisplayName("busca por CPF devolve lista — a unicidade nao e garantida pelo banco")
    void porCpf() {
        assertThat(repositorio.porCpf("26716608044"))
                .extracting(PacienteRegistro::cdPaciente)
                .containsExactly(10001);
    }

    @Test
    @DisplayName("busca por CNS")
    void porCns() {
        assertThat(repositorio.porCns("190777220470008"))
                .extracting(PacienteRegistro::cdPaciente)
                .containsExactly(10004);
    }

    @Test
    @DisplayName("documento inexistente devolve lista vazia")
    void documentoInexistente() {
        assertThat(repositorio.porCpf("00000000000")).isEmpty();
        assertThat(repositorio.porCns("000000000000000")).isEmpty();
    }

    @Test
    @DisplayName("busca por data de nascimento")
    void porDataNascimento() {
        assertThat(repositorio.porDataNascimento(LocalDate.of(1940, 8, 4)))
                .extracting(PacienteRegistro::cdPaciente)
                .contains(10001);
    }

    @Test
    @DisplayName("busca por nome sem acento encontra nome acentuado — RF-03")
    void porNomeSemAcento() {
        var resultado = repositorio.porNome("sergio", 50);

        assertThat(resultado.registros())
                .isNotEmpty()
                .allMatch(r -> r.nmPaciente().toLowerCase().contains("s"));
        assertThat(resultado.registros())
                .extracting(PacienteRegistro::nmPaciente)
                .anyMatch(n -> n.contains("Sérgio"));
    }

    @Test
    @DisplayName("busca por nome tambem alcanca o nome social")
    void porNomeSocial() {
        var resultado = repositorio.porNome("juliana silva rocha", 50);

        assertThat(resultado.registros())
                .extracting(PacienteRegistro::cdPaciente)
                .contains(10011);
    }

    @Test
    @DisplayName("a varredura examina a base inteira mas so materializa o limite — custo de RA-02")
    void varreduraLimitada() {
        var resultado = repositorio.porNome("a", 5);

        assertThat(resultado.registros()).hasSize(5);
        assertThat(resultado.examinados()).isEqualTo(200);
    }

    @Test
    @DisplayName("COALESCE recupera os 14 pacientes sem dt_atualizacao — sem ele ficariam invisiveis para sempre")
    void janelaIncrementalRecuperaSemCarimbo() {
        // Paciente 10179: dt_atualizacao nula, dt_cadastro em 09/08/2025.
        var janela = repositorio.alteradosNaJanela(
                LocalDateTime.of(2025, 8, 1, 0, 0),
                LocalDateTime.of(2025, 8, 31, 23, 59),
                500);

        assertThat(janela).extracting(PacienteRegistro::cdPaciente).contains(10179);
        assertThat(janela)
                .filteredOn(r -> r.cdPaciente() == 10179)
                .allMatch(r -> r.ultimaAtualizacao().toLocalDate().equals(LocalDate.of(2025, 8, 9)));
    }

    @Test
    @DisplayName("todo paciente tem carimbo de referencia, mesmo sem dt_atualizacao")
    void todosTemCarimbo() {
        var todos = repositorio.alteradosNaJanela(null, null, 1000);

        assertThat(todos).hasSize(200);
        assertThat(todos).allMatch(r -> r.ultimaAtualizacao() != null);
    }

    @Test
    @DisplayName("contatos do paciente")
    void contatos() {
        assertThat(repositorio.contatosDe(10001)).isNotEmpty();
    }

    @Test
    @DisplayName("enderecos com municipio resolvido por LEFT JOIN")
    void enderecos() {
        var comEndereco = repositorio.alteradosNaJanela(null, null, 1000).stream()
                .map(r -> repositorio.enderecosDe(r.cdPaciente()))
                .filter(e -> !e.isEmpty())
                .findFirst()
                .orElseThrow();

        assertThat(comEndereco).allMatch(e -> e.nmMunicipio() != null);
    }
}

