import static org.assertj.core.api.Assertions.assertThat;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicInteger;
import org.hl7.fhir.r4.model.Patient;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * RA-03: cache em memoria com TTL curto e permitido; base espelhada nao e.
 */
@DisplayName("Cache em memoria do paciente")
class PacienteCacheTest {

    /** Relogio controlado, para o teste nao depender de espera real. */
    private static final class RelogioAjustavel extends Clock {
        private Instant agora = Instant.parse("2026-08-24T12:00:00Z");

        void avancar(Duration quanto) {
            agora = agora.plus(quanto);
        }

        @Override
        public Instant instant() {
            return agora;
        }

        @Override
        public ZoneOffset getZone() {
            return ZoneOffset.UTC;
        }

        @Override
        public Clock withZone(java.time.ZoneId zona) {
            return this;
        }
    }

    private Patient paciente(String id) {
        var p = new Patient();
        p.setId(id);
        return p;
    }

    @Test
    @DisplayName("a segunda leitura dentro do TTL nao vai a origem")
    void serveDoCacheDentroDoTtl() {
        var relogio = new RelogioAjustavel();
        var cache = new PacienteCache(Duration.ofSeconds(5), relogio);
        var idasAOrigem = new AtomicInteger();

        cache.obter(10001, () -> {
            idasAOrigem.incrementAndGet();
            return Optional.of(paciente("10001"));
        });
        relogio.avancar(Duration.ofSeconds(4));
        var segunda = cache.obter(10001, () -> {
            idasAOrigem.incrementAndGet();
            return Optional.of(paciente("10001"));
        });

        assertThat(idasAOrigem).hasValue(1);
        assertThat(segunda).isPresent();
    }

    @Test
    @DisplayName("passado o TTL, a entrada expira e a origem e consultada de novo")
    void expiraNoPrazo() {
        var relogio = new RelogioAjustavel();
        var cache = new PacienteCache(Duration.ofSeconds(5), relogio);
        var idasAOrigem = new AtomicInteger();

        cache.obter(10001, () -> {
            idasAOrigem.incrementAndGet();
            return Optional.of(paciente("10001"));
        });
        relogio.avancar(Duration.ofSeconds(6));
        cache.obter(10001, () -> {
            idasAOrigem.incrementAndGet();
            return Optional.of(paciente("10001"));
        });

        assertThat(idasAOrigem).hasValue(2);
    }

    @Test
    @DisplayName("paciente inexistente nao e guardado — nao cria cache negativo")
    void naoGuardaAusencia() {
        var cache = new PacienteCache(Duration.ofSeconds(5), new RelogioAjustavel());

        assertThat(cache.obter(999999, Optional::empty)).isEmpty();
        assertThat(cache.tamanho()).isZero();
    }

    @Test
    @DisplayName("nada e escrito em disco — RA-03 proibe copia persistente")
    void nadaEmDisco() throws Exception {
        var antes = arquivosNoDiretorioDeTrabalho();

        var cache = new PacienteCache(Duration.ofSeconds(5), new RelogioAjustavel());
        for (int codigo = 1; codigo <= 200; codigo++) {
            int atual = codigo;
            cache.obter(atual, () -> Optional.of(paciente(String.valueOf(atual))));
        }

        assertThat(cache.tamanho()).isEqualTo(200);
        assertThat(arquivosNoDiretorioDeTrabalho()).isEqualTo(antes);

        cache.limpar();
        assertThat(cache.tamanho()).isZero();
    }

    private static long arquivosNoDiretorioDeTrabalho() throws Exception {
        try (var caminhos = java.nio.file.Files.walk(java.nio.file.Path.of("."), 2)) {
            return caminhos.filter(java.nio.file.Files::isRegularFile).count();
        }
    }
}

