package br.com.vitaflow.fhirfacade.apoio;

import ca.uhn.fhir.context.FhirContext;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import org.hl7.fhir.instance.model.api.IBaseResource;

/**
 * Cliente HTTP cru.
 *
 * <p>Deliberadamente sem o cliente do HAPI: varios testes precisam afirmar o que
 * esta — e o que nao esta — na URL da requisicao, e um cliente que monta a URL
 * sozinho esconderia justamente isso.
 */
public class ClienteHttp {

    private final HttpClient http = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(10))
            .followRedirects(HttpClient.Redirect.NEVER)
            .build();

    private final FhirContext contexto = FhirContext.forR4();
    private final String base;

    public ClienteHttp(int porta) {
        this.base = "http://localhost:" + porta + "/fhir";
    }

    public String base() {
        return base;
    }

    public HttpResponse<String> get(String caminhoEQuery) throws Exception {
        var requisicao = HttpRequest.newBuilder(URI.create(base + caminhoEQuery))
                .header("Accept", "application/fhir+json")
                .header("X-Consumidor", "vitaflow-testes")
                .GET().build();
        return http.send(requisicao, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
    }

    public HttpResponse<String> getAbsoluto(String url) throws Exception {
        return http.send(HttpRequest.newBuilder(URI.create(url)).GET().build(),
                HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
    }

    /** POST [base]/Patient/_search — o caminho que mantem o CPF fora da URL. */
    public HttpResponse<String> buscaPorFormulario(String corpoUrlEncoded) throws Exception {
        var requisicao = HttpRequest.newBuilder(URI.create(base + "/Patient/_search"))
                .header("Content-Type", "application/x-www-form-urlencoded")
                .header("Accept", "application/fhir+json")
                .header("X-Consumidor", "vitaflow-testes")
                .POST(HttpRequest.BodyPublishers.ofString(corpoUrlEncoded, StandardCharsets.UTF_8))
                .build();
        return http.send(requisicao, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
    }

    public HttpResponse<String> enviar(String metodo, String caminho, String corpo) throws Exception {
        var publicador = corpo == null
                ? HttpRequest.BodyPublishers.noBody()
                : HttpRequest.BodyPublishers.ofString(corpo, StandardCharsets.UTF_8);
        var requisicao = HttpRequest.newBuilder(URI.create(base + caminho))
                .header("Content-Type", "application/fhir+json")
                .header("Accept", "application/fhir+json")
                .method(metodo, publicador)
                .build();
        return http.send(requisicao, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
    }

    public <T extends IBaseResource> T interpretar(String json, Class<T> tipo) {
        return contexto.newJsonParser().parseResource(tipo, json);
    }

    public String serializar(IBaseResource recurso) {
        return contexto.newJsonParser().encodeResourceToString(recurso);
    }
}

