package br.com.vitaflow.fhirfacade.servidor;

import static org.assertj.core.api.Assertions.assertThat;

import br.com.vitaflow.fhirfacade.apoio.BaseIntegracao;
import br.com.vitaflow.fhirfacade.apoio.ClienteHttp;
import br.com.vitaflow.fhirfacade.traducao.Sistemas;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import org.hl7.fhir.r4.model.Bundle;
import org.hl7.fhir.r4.model.OperationOutcome;
import org.hl7.fhir.r4.model.Patient;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@DisplayName("Fachada FHIR: interacoes de leitura e busca")
class FachadaFhirIT extends BaseIntegracao {

    private static final String CPF_DE_TESTE = "26716608044";

    @LocalServerPort
    int porta;

    private ClienteHttp cliente;

    @BeforeEach
    void prepararCliente() {
        cliente = new ClienteHttp(porta);
    }

    private Bundle bundle(String json) {
        return cliente.interpretar(json, Bundle.class);
    }

    private static String codigos(Bundle bundle) {
        return bundle.getEntry().stream()
                .map(e -> e.getResource().getIdElement().getIdPart())
                .reduce("", (a, b) -> a + b + ",");
    }

    // ------------------------------------------------------------------ read

    @Nested
    @DisplayName("Requirement: Leitura de paciente por identificador logico")
    class Leitura {

        @Test
        @DisplayName("Scenario: paciente existente")
        void pacienteExistente() throws Exception {
            var resposta = cliente.get("/Patient/10001");

            assertThat(resposta.statusCode()).isEqualTo(200);
            var paciente = cliente.interpretar(resposta.body(), Patient.class);
            assertThat(paciente.getIdElement().getIdPart()).isEqualTo("10001");
            assertThat(paciente.getNameFirstRep().getText()).isEqualTo("Luciana Almeida Nascimento");
        }

        @Test
        @DisplayName("Scenario: paciente inexistente devolve 404 com OperationOutcome")
        void pacienteInexistente() throws Exception {
            var resposta = cliente.get("/Patient/999999");

            assertThat(resposta.statusCode()).isEqualTo(404);
            assertThat(cliente.interpretar(resposta.body(), OperationOutcome.class).getIssue()).isNotEmpty();
        }

        @Test
        @DisplayName("id que nao e numero devolve 404, e nao erro de servidor")
        void idNaoNumerico() throws Exception {
            assertThat(cliente.get("/Patient/abc").statusCode()).isEqualTo(404);
        }

        @Test
        @DisplayName("paciente sem CPF e sem CNS e retornavel — 3,5% da base")
        void pacienteSemDocumento() throws Exception {
            var resposta = cliente.get("/Patient/10023");

            assertThat(resposta.statusCode()).isEqualTo(200);
            var paciente = cliente.interpretar(resposta.body(), Patient.class);
            assertThat(paciente.getIdentifier()).hasSize(1);
            assertThat(paciente.getIdentifierFirstRep().getSystem()).isEqualTo(Sistemas.CD_PACIENTE);
        }
    }

    // ---------------------------------------------------------- identificador

    @Nested
    @DisplayName("Requirement: Busca por identificador de negocio")
    class PorIdentificador {

        @Test
        @DisplayName("Scenario: busca por CNS")
        void porCns() throws Exception {
            var resposta = cliente.get("/Patient?identifier="
                    + URLEncoder.encode(Sistemas.CNS + "|190777220470008", StandardCharsets.UTF_8));

            assertThat(resposta.statusCode()).isEqualTo(200);
            assertThat(codigos(bundle(resposta.body()))).contains("10004");
        }

        @Test
        @DisplayName("Scenario: documento inexistente devolve total zero com 200, nao 404")
        void documentoInexistente() throws Exception {
            var resposta = cliente.get("/Patient?identifier="
                    + URLEncoder.encode(Sistemas.CNS + "|000000000000000", StandardCharsets.UTF_8));

            assertThat(resposta.statusCode()).isEqualTo(200);
            var resultado = bundle(resposta.body());
            assertThat(resultado.getType()).isEqualTo(Bundle.BundleType.SEARCHSET);
            assertThat(resultado.getEntry()).isEmpty();
        }

        @Test
        @DisplayName("busca pelo codigo interno qualificado pelo system")
        void porCodigoInterno() throws Exception {
            var resposta = cliente.get("/Patient?identifier="
                    + URLEncoder.encode(Sistemas.CD_PACIENTE + "|10011", StandardCharsets.UTF_8));

            assertThat(codigos(bundle(resposta.body()))).contains("10011");
        }

        @Test
        @DisplayName("system nao suportado e recusado em vez de devolver vazio silenciosamente")
        void systemNaoSuportado() throws Exception {
            var resposta = cliente.get("/Patient?identifier="
                    + URLEncoder.encode("http://exemplo.org/outro|123", StandardCharsets.UTF_8));

            assertThat(resposta.statusCode()).isEqualTo(400);
        }
    }

    // ------------------------------------------------------ CPF fora da URL

    @Nested
    @DisplayName("Requirement: Proibicao de CPF em URL")
    class CpfForaDaUrl {

        @Test
        @DisplayName("Scenario: busca por CPF pelo corpo do POST /_search")
        void buscaPorCpfNoCorpo() throws Exception {
            var corpo = "identifier=" + URLEncoder.encode(Sistemas.CPF + "|" + CPF_DE_TESTE,
                    StandardCharsets.UTF_8);

            var resposta = cliente.buscaPorFormulario(corpo);

            assertThat(resposta.statusCode()).isEqualTo(200);
            assertThat(codigos(bundle(resposta.body()))).contains("10001");

            // A URL efetivamente chamada nao carrega o CPF.
            assertThat(resposta.uri().toString()).doesNotContain(CPF_DE_TESTE);
            assertThat(resposta.uri().getQuery()).isNull();
        }

        @Test
        @DisplayName("Scenario: GET com CPF na cadeia de consulta e recusado sem ecoar o valor")
        void getComCpfNaUrl() throws Exception {
            var resposta = cliente.get("/Patient?identifier=" + CPF_DE_TESTE);

            assertThat(resposta.statusCode()).isEqualTo(400);
            assertThat(resposta.body()).doesNotContain(CPF_DE_TESTE);

            var problema = cliente.interpretar(resposta.body(), OperationOutcome.class);
            assertThat(problema.getIssueFirstRep().getDiagnostics()).contains("_search");
        }

        @Test
        @DisplayName("GET com CPF qualificado pelo system tambem e recusado")
        void getComCpfQualificado() throws Exception {
            var resposta = cliente.get("/Patient?identifier="
                    + URLEncoder.encode(Sistemas.CPF + "|" + CPF_DE_TESTE, StandardCharsets.UTF_8));

            assertThat(resposta.statusCode()).isEqualTo(400);
            assertThat(resposta.body()).doesNotContain(CPF_DE_TESTE);
        }

        @Test
        @DisplayName("CPF mascarado na URL tambem e recusado")
        void getComCpfMascarado() throws Exception {
            assertThat(cliente.get("/Patient?identifier=269.166.080-44").statusCode()).isEqualTo(400);
        }

        @Test
        @DisplayName("CNS de 15 digitos na URL continua permitido — nao e CPF")
        void cnsNaUrlEhPermitido() throws Exception {
            assertThat(cliente.get("/Patient?identifier="
                    + URLEncoder.encode(Sistemas.CNS + "|190777220470008", StandardCharsets.UTF_8))
                    .statusCode()).isEqualTo(200);
        }
    }

    // ------------------------------------------------------------- nome da mae

    @Nested
    @DisplayName("Requirement: Nome da mae fora do escopo de exposicao")
    class NomeDaMae {

        @Test
        @DisplayName("Scenario: tentativa de busca por nome da mae e recusada")
        void buscaPorNomeDaMaeRecusada() throws Exception {
            var resposta = cliente.get("/Patient?mothersMaidenName=Cristiane");

            assertThat(resposta.statusCode()).isEqualTo(400);
            assertThat(resposta.body()).doesNotContain("Cristiane");
            assertThat(cliente.interpretar(resposta.body(), OperationOutcome.class)
                    .getIssueFirstRep().getDiagnostics()).contains("PD-03");
        }

        @Test
        @DisplayName("variacoes do nome do parametro tambem sao recusadas")
        void variacoesRecusadas() throws Exception {
            assertThat(cliente.get("/Patient?nm_mae=Ana").statusCode()).isEqualTo(400);
            assertThat(cliente.get("/Patient?nomeMae=Ana").statusCode()).isEqualTo(400);
            assertThat(cliente.get("/Patient?mother=Ana").statusCode()).isEqualTo(400);
        }
    }

    // ------------------------------------------------------------------- nome

    @Nested
    @DisplayName("Requirement: Busca de paciente por nome")
    class PorNome {

        @Test
        @DisplayName("Scenario: busca sem acento encontra nome acentuado")
        void semAcentoEncontraAcentuado() throws Exception {
            var resposta = cliente.get("/Patient?name=sergio");

            assertThat(resposta.statusCode()).isEqualTo(200);
            assertThat(codigos(bundle(resposta.body()))).contains("10044");
        }

        @Test
        @DisplayName("Scenario: busca corresponde ao nome social")
        void encontraPeloNomeSocial() throws Exception {
            var resposta = cliente.get("/Patient?name=juliana%20silva%20rocha");

            assertThat(codigos(bundle(resposta.body()))).contains("10011");
        }

        @Test
        @DisplayName("busca insensivel a caixa")
        void insensivelACaixa() throws Exception {
            assertThat(bundle(cliente.get("/Patient?name=LUCIANA").body()).getEntry()).isNotEmpty();
        }

        @Test
        @DisplayName("o limite obrigatorio contem o resultado — termo de alta correspondencia")
        void limiteObrigatorio() throws Exception {
            var resultado = bundle(cliente.get("/Patient?name=a").body());

            assertThat(resultado.getEntry()).isNotEmpty().hasSizeLessThanOrEqualTo(50);
        }
    }

    // -------------------------------------------------------------- nascimento

    @Nested
    @DisplayName("Requirement: Busca por data de nascimento")
    class PorNascimento {

        @Test
        @DisplayName("Scenario: busca por data exata")
        void dataExata() throws Exception {
            var resposta = cliente.get("/Patient?birthdate=1940-08-04");

            assertThat(resposta.statusCode()).isEqualTo(200);
            assertThat(codigos(bundle(resposta.body()))).contains("10001");
        }

        @Test
        @DisplayName("data invalida devolve 400 com OperationOutcome")
        void dataInvalida() throws Exception {
            assertThat(cliente.get("/Patient?birthdate=31-02-1900").statusCode()).isEqualTo(400);
        }
    }

    // ------------------------------------------------------------- incremental

    @Nested
    @DisplayName("Requirement: Sincronizacao incremental")
    class Incremental {

        @Test
        @DisplayName("Scenario: paciente sem carimbo entra na janela pelo COALESCE com dt_cadastro")
        void semCarimboEntraNaJanela() throws Exception {
            var resposta = cliente.get("/Patient?_lastUpdated=ge2025-08-01&_lastUpdated=le2025-08-31");

            assertThat(resposta.statusCode()).isEqualTo(200);
            var resultado = bundle(resposta.body());
            assertThat(codigos(resultado)).contains("10179");

            var recuperado = resultado.getEntry().stream()
                    .map(e -> (Patient) e.getResource())
                    .filter(p -> "10179".equals(p.getIdElement().getIdPart()))
                    .findFirst().orElseThrow();

            // O valor exposto e o mesmo que filtrou: dt_cadastro de 09/08/2025.
            assertThat(recuperado.getMeta().getLastUpdated()).isNotNull();
            assertThat(recuperado.getMeta().getLastUpdated().toInstant().toString())
                    .startsWith("2025-08-09");
        }

        @Test
        @DisplayName("Scenario: carimbo no futuro aparece em qualquer janela que termine no presente")
        void carimboNoFuturo() throws Exception {
            var resposta = cliente.get("/Patient?_lastUpdated=ge2026-11-01");

            // 17 registros tem dt_atualizacao no futuro. Eles reaparecem sempre —
            // por isso o consumidor precisa ser idempotente.
            assertThat(bundle(resposta.body()).getEntry()).isNotEmpty();
        }

        @Test
        @DisplayName("meta.lastUpdated e o mesmo valor usado no filtro")
        void carimboExpostoIgualAoFiltrado() throws Exception {
            var paciente = cliente.interpretar(cliente.get("/Patient/10002").body(), Patient.class);

            assertThat(paciente.getMeta().getLastUpdated()).isNotNull();
        }
    }

    // ------------------------------------------------------------- criterios

    @Test
    @DisplayName("busca sem nenhum criterio e recusada")
    void buscaSemCriterio() throws Exception {
        assertThat(cliente.get("/Patient").statusCode()).isEqualTo(400);
    }

    @Test
    @DisplayName("mais de um criterio e recusado explicitamente, em vez de um filtro ser ignorado")
    void maisDeUmCriterio() throws Exception {
        var resposta = cliente.get("/Patient?name=luciana&birthdate=1940-08-04");

        assertThat(resposta.statusCode()).isEqualTo(400);
        assertThat(cliente.interpretar(resposta.body(), OperationOutcome.class)
                .getIssueFirstRep().getDiagnostics()).contains("um criterio");
    }
}

