            var resposta = cliente.get("/Patient?name=juliana%20silva%20rocha");

            assertThat(codigos(bundle(resposta.body()))).contains("10011");
        }

        @Test
        @DisplayName("busca insensivel a caixa")
        void insensivelACaixa() throws Exception {
            assertThat(bundle(cliente.get("/Patient?name=LUCIANA").body()).getEntry()).isNotEmpty();
        }

        @Test
        @DisplayName("o limite obrigatorio contem o resultado — termo de alta correspondencia")
        void limiteObrigatorio() throws Exception {
            var resultado = bundle(cliente.get("/Patient?name=a").body());

            assertThat(resultado.getEntry()).isNotEmpty().hasSizeLessThanOrEqualTo(50);
        }
    }

    // -------------------------------------------------------------- nascimento

    @Nested
    @DisplayName("Requirement: Busca por data de nascimento")
    class PorNascimento {

        @Test
        @DisplayName("Scenario: busca por data exata")
        void dataExata() throws Exception {
            var resposta = cliente.get("/Patient?birthdate=1940-08-04");

            assertThat(resposta.statusCode()).isEqualTo(200);
            assertThat(codigos(bundle(resposta.body()))).contains("10001");
        }

        @Test
        @DisplayName("data invalida devolve 400 com OperationOutcome")
        void dataInvalida() throws Exception {
            assertThat(cliente.get("/Patient?birthdate=31-02-1900").statusCode()).isEqualTo(400);
        }
    }

    // ------------------------------------------------------------- incremental

    @Nested
    @DisplayName("Requirement: Sincronizacao incremental")
    class Incremental {

        @Test
        @DisplayName("Scenario: paciente sem carimbo entra na janela pelo COALESCE com dt_cadastro")
        void semCarimboEntraNaJanela() throws Exception {
            var resposta = cliente.get("/Patient?_lastUpdated=ge2025-08-01&_lastUpdated=le2025-08-31");

            assertThat(resposta.statusCode()).isEqualTo(200);
            var resultado = bundle(resposta.body());
            assertThat(codigos(resultado)).contains("10179");

            var recuperado = resultado.getEntry().stream()
                    .map(e -> (Patient) e.getResource())
                    .filter(p -> "10179".equals(p.getIdElement().getIdPart()))
                    .findFirst().orElseThrow();

            // O valor exposto e o mesmo que filtrou: dt_cadastro de 09/08/2025.
            assertThat(recuperado.getMeta().getLastUpdated()).isNotNull();
            assertThat(recuperado.getMeta().getLastUpdated().toInstant().toString())
                    .startsWith("2025-08-09");
        }

        @Test
        @DisplayName("Scenario: carimbo no futuro aparece em qualquer janela que termine no presente")
        void carimboNoFuturo() throws Exception {
            var resposta = cliente.get("/Patient?_lastUpdated=ge2026-11-01");

            // 17 registros tem dt_atualizacao no futuro. Eles reaparecem sempre —
            // por isso o consumidor precisa ser idempotente.
            assertThat(bundle(resposta.body()).getEntry()).isNotEmpty();
        }

        @Test
        @DisplayName("meta.lastUpdated e o mesmo valor usado no filtro")
        void carimboExpostoIgualAoFiltrado() throws Exception {
            var paciente = cliente.interpretar(cliente.get("/Patient/10002").body(), Patient.class);

            assertThat(paciente.getMeta().getLastUpdated()).isNotNull();
        }
    }

    // ------------------------------------------------------------- criterios

    @Test
    @DisplayName("busca sem nenhum criterio e recusada")
    void buscaSemCriterio() throws Exception {
        assertThat(cliente.get("/Patient").statusCode()).isEqualTo(400);
    }

    @Test
    @DisplayName("mais de um criterio e recusado explicitamente, em vez de um filtro ser ignorado")
    void maisDeUmCriterio() throws Exception {
        var resposta = cliente.get("/Patient?name=luciana&birthdate=1940-08-04");

        assertThat(resposta.statusCode()).isEqualTo(400);
        assertThat(cliente.interpretar(resposta.body(), OperationOutcome.class)
                .getIssueFirstRep().getDiagnostics()).contains("um criterio");
    }
}

