package br.com.vitaflow.fhirfacade.servidor;

import ca.uhn.fhir.interceptor.api.Hook;
import ca.uhn.fhir.interceptor.api.Interceptor;
import ca.uhn.fhir.interceptor.api.Pointcut;
import org.hl7.fhir.instance.model.api.IBaseConformance;
import org.hl7.fhir.r4.model.CapabilityStatement;
import org.springframework.stereotype.Component;

/**
 * Escreve no CapabilityStatement o que o consumidor precisa saber antes de
 * confiar nos dados — com os numeros, e nao com a premissa.
 *
 * <p>Isto nao e enfeite. Duas integracoes anteriores morreram porque o
 * consumidor assumiu coisas sobre este cadastro que o dado nao sustenta. O lugar
 * de desfazer essa suposicao e o contrato da interface, nao um documento a parte
 * que ninguem le.
 */
@Interceptor
@Component
public class DocumentacaoDaFachadaInterceptor {

    static final String AVISOS = """
            Fachada FHIR R4 somente leitura sobre o cadastro de pacientes do SIGH \
            (Hospital Santa Aurora). Consulta ao vivo contra a replica; nenhum dado \
            e migrado, copiado ou gravado.

            O QUE O DADO DE ORIGEM NAO GARANTE — verificado contra a base, nao suposto:

            1. NEM TODO PACIENTE TEM CPF. 15,5% do cadastro nao tem CPF e 3,5% nao tem \
            CPF nem CNS. Identifique o paciente por Patient.id (codigo interno do SIGH), \
            que e o unico identificador presente em 100% dos registros. CPF e CNS sao \
            identificadores de negocio opcionais em Patient.identifier.

            2. active=false NAO SIGNIFICA OBITO. Patient.active reflete a situacao \
            administrativa do cadastro; o obito tem elemento proprio \
            (Patient.deceasedDateTime). Na base verificada, 9 dos 15 cadastros inativos \
            correspondem a pessoas vivas. Nunca derive um do outro.

            3. A SINCRONIZACAO INCREMENTAL E INCOMPLETA. O filtro _lastUpdated usa \
            COALESCE(dt_atualizacao, dt_cadastro) porque 7% dos registros nao tem carimbo \
            de atualizacao na origem. Para esses 7%, o valor devolvido e o instante de \
            CRIACAO, e alteracoes feitas por processo batch que nao passa pela trigger da \
            aplicacao nao movem o carimbo e nao serao detectadas. UMA VARREDURA COMPLETA \
            PERIODICA E OBRIGATORIA, nao opcional. Alem disso, 8,5% dos registros tem \
            carimbo com data no futuro e reaparecem em toda janela: o consumidor precisa \
            ser idempotente.

            4. NOME SOCIAL TEM PRECEDENCIA DE EXIBICAO. Quando existir, vem em \
            Patient.name com use=usual e em primeiro lugar; o nome civil vem com \
            use=official e continua disponivel para documentos. Exiba o usual.

            5. NOME DA MAE NAO E EXPOSTO, em nenhuma forma e sob nenhum parametro \
            (restricao do Encarregado de Dados).

            6. CPF NAO TRAFEGA EM URL. Busca por CPF apenas via \
            POST [base]/Patient/_search, com o criterio no corpo.

            7. gender=unknown pode significar 'nao informado' ou o valor 'I' herdado da \
            migracao de 2013, cujo significado o fornecedor nao soube esclarecer. O valor \
            bruto de origem e preservado numa extensao no elemento gender.

            8. DESEMPENHO: a busca por nome faz varredura completa do cadastro, porque a \
            insensibilidade a acento e resolvida na aplicacao (nao e permitido alterar o \
            banco do fornecedor). Ela nao atende o alvo de 800 ms do percentil 95, que \
            vale para a leitura por identificador.
            """;

    @Hook(Pointcut.SERVER_CAPABILITY_STATEMENT_GENERATED)
    public void descrever(IBaseConformance capacidades) {
        if (capacidades instanceof CapabilityStatement declaracao) {
            declaracao.setTitle("Fachada FHIR R4 — Paciente do SIGH");
            declaracao.getImplementation().setDescription(AVISOS);
            declaracao.getRest().forEach(rest -> rest.getResource().stream()
                    .filter(recurso -> "Patient".equals(recurso.getType()))
                    .forEach(recurso -> recurso.setDocumentation(AVISOS)));
        }
    }
}

