package br.com.vitaflow.fhirfacade.servidor;

import ca.uhn.fhir.context.FhirContext;
import java.util.List;
import org.springframework.boot.web.servlet.ServletRegistrationBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.config.annotation.ViewControllerRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

@Configuration
public class FhirServerConfig implements WebMvcConfigurer {

    public static final String CAMINHO_BASE = "/fhir";

    @Bean
    public FhirContext contextoR4() {
        return FhirContext.forR4();
    }

    @Bean
    public ServletRegistrationBean<FhirFacadeServlet> servidorFhir(
            FhirContext contexto,
            PatientResourceProvider provider,
            EscritaBloqueadaInterceptor escritaBloqueada,
            ProtecaoDeDadosInterceptor protecaoDeDados) {

        var servlet = new FhirFacadeServlet(contexto, provider,
                List.of(escritaBloqueada, protecaoDeDados));

        var registro = new ServletRegistrationBean<>(servlet, CAMINHO_BASE + "/*");
        registro.setName("fhir-facade");
        registro.setLoadOnStartup(1);
        return registro;
    }

    /**
     * O OpenApiInterceptor publica a interface navegavel sob a base do servidor
     * FHIR, ou seja, em /fhir/swagger-ui/. Este redirecionamento mantem
     * /swagger-ui/ funcionando como atalho.
     */
    @Override
    public void addViewControllers(ViewControllerRegistry registro) {
        registro.addRedirectViewController("/swagger-ui/", CAMINHO_BASE + "/swagger-ui/");
        registro.addRedirectViewController("/swagger-ui", CAMINHO_BASE + "/swagger-ui/");
    }
}

