/**
 * RA-01 / RNF-02: nenhuma escrita no SIGH, por nenhum caminho.
 *
 * <p>Alem do codigo 405, cada teste afirma que o repositorio nao foi tocado — a
 * recusa acontece antes de qualquer consulta chegar ao banco.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@DisplayName("Requirement: Somente leitura — interacoes de escrita recusadas")
class EscritaBloqueadaIT extends BaseIntegracao {

    @LocalServerPort
    int porta;

    @MockitoSpyBean
    PacienteRepository repositorio;

    private ClienteHttp cliente;

    @BeforeEach
    void preparar() {
        cliente = new ClienteHttp(porta);
        clearInvocations(repositorio);
    }

    private String pacienteEmJson() {
        var paciente = new Patient();
        paciente.setId("10001");
        return cliente.serializar(paciente);
    }

    @Test
    @DisplayName("Scenario: PUT devolve 405 e nao consulta o banco")
    void putRecusado() throws Exception {
        var resposta = cliente.enviar("PUT", "/Patient/10001", pacienteEmJson());

        assertThat(resposta.statusCode()).isEqualTo(405);
        assertThat(cliente.interpretar(resposta.body(), OperationOutcome.class).getIssue()).isNotEmpty();
        verifyNoInteractions(repositorio);
    }

    @Test
    @DisplayName("POST de criacao devolve 405 e nao consulta o banco")
    void postDeCriacaoRecusado() throws Exception {
        var resposta = cliente.enviar("POST", "/Patient", pacienteEmJson());

        assertThat(resposta.statusCode()).isEqualTo(405);
        verifyNoInteractions(repositorio);
    }

    @Test
    @DisplayName("PATCH devolve 405 e nao consulta o banco")
    void patchRecusado() throws Exception {
        var resposta = cliente.enviar("PATCH", "/Patient/10001", "[]");

        assertThat(resposta.statusCode()).isEqualTo(405);
        verifyNoInteractions(repositorio);
    }

    @Test
    @DisplayName("DELETE devolve 405 e nao consulta o banco")
    void deleteRecusado() throws Exception {
        var resposta = cliente.enviar("DELETE", "/Patient/10001", null);

        assertThat(resposta.statusCode()).isEqualTo(405);
        verifyNoInteractions(repositorio);
    }

    @Test
    @DisplayName("a transacao em lote tambem e recusada")
    void transacaoRecusada() throws Exception {
        assertThat(cliente.enviar("POST", "", "{\"resourceType\":\"Bundle\",\"type\":\"transaction\"}")
                .statusCode()).isEqualTo(405);
        verifyNoInteractions(repositorio);
    }

    @Test
    @DisplayName("o POST /_search continua passando — e o caminho que tira o CPF da URL")
    void buscaPorFormularioContinuaFuncionando() throws Exception {
        var resposta = cliente.buscaPorFormulario("name=luciana");

        assertThat(resposta.statusCode()).isEqualTo(200);
    }
}

