package br.com.vitaflow.fhirfacade.seguranca;

import static org.assertj.core.api.Assertions.assertThat;

import br.com.vitaflow.fhirfacade.apoio.BaseIntegracao;
import br.com.vitaflow.fhirfacade.apoio.ClienteHttp;
import br.com.vitaflow.fhirfacade.servico.PacienteService;
import ca.uhn.fhir.context.FhirContext;
import java.util.List;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * PD-03: nome da mae fora do escopo, em qualquer forma.
 *
 * <p>Este teste nao confia na leitura do codigo. Ele pega os 200 nomes de mae
 * direto do banco e varre a resposta serializada de todos os 200 pacientes
 * procurando cada um deles.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@DisplayName("Requirement: Nome da mae nao alcanca o recurso")
class NomeDaMaeIT extends BaseIntegracao {

    @LocalServerPort
    int porta;

    @Autowired
    PacienteService servico;

    @Autowired
    JdbcTemplate jdbc;

    @Test
    @DisplayName("Scenario: nenhum dos 192 nomes de mae aparece na serializacao dos 200 pacientes")
    void nenhumNomeDeMaeVazaNoRecurso() {
        List<String> nomesDeMae = jdbc.queryForList(
                "SELECT nm_mae FROM sigh.paciente WHERE nm_mae IS NOT NULL", String.class);
        assertThat(nomesDeMae).isNotEmpty();

        var parser = FhirContext.forR4().newJsonParser();
        var todos = servico.alteradosNaJanela(null, null, 1000);
        assertThat(todos).hasSize(200);

        var serializado = todos.stream()
                .map(parser::encodeResourceToString)
                .reduce(new StringBuilder(), StringBuilder::append, StringBuilder::append)
                .toString();

        for (var nomeDeMae : nomesDeMae) {
            assertThat(serializado)
                    .as("nome da mae vazou no recurso: %s", nomeDeMae)
                    .doesNotContain(nomeDeMae);
        }
    }

    @Test
    @DisplayName("a consulta ao banco nao seleciona a coluna nm_mae")
    void aConsultaNaoLeAColuna() {
        assertThat(br.com.vitaflow.fhirfacade.origem.PacienteRepository.COLUNAS_PACIENTE)
                .doesNotContain("nm_mae");
    }

    @Test
    @DisplayName("o registro lido da origem nao tem sequer um campo para nome da mae")
    void oTipoNaoTemOCampo() {
        var campos = java.util.Arrays.stream(
                        br.com.vitaflow.fhirfacade.origem.PacienteRegistro.class.getRecordComponents())
                .map(java.lang.reflect.RecordComponent::getName)
                .toList();

        assertThat(campos).noneMatch(nome -> nome.toLowerCase().contains("mae"));
    }

    @Test
    @DisplayName("a resposta HTTP de um paciente conhecido nao traz o nome da mae dele")
    void respostaHttpNaoTrazNomeDaMae() throws Exception {
        var nomeDaMae = jdbc.queryForObject(
                "SELECT nm_mae FROM sigh.paciente WHERE cd_paciente = 10001", String.class);

        var resposta = new ClienteHttp(porta).get("/Patient/10001");

        assertThat(resposta.body()).doesNotContain(nomeDaMae);
    }
}

