import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;

/**
 * RNF-08: os recursos precisam passar em validacao de conformidade.
 *
 * <p>Inclui os recursos derivados de registro com dado ausente ou incoerente na
 * origem — que sao justamente os que quebrariam.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.NONE)
@DisplayName("Conformidade com FHIR R4")
class ConformidadeFhirIT extends BaseIntegracao {

    private static FhirContext contexto;
    private static FhirValidator validador;

    @Autowired
    PacienteService servico;

    @BeforeAll
    static void montarValidador() {
        contexto = FhirContext.forR4();
        var apoio = new ValidationSupportChain(
                contexto.getValidationSupport(),
                new InMemoryTerminologyServerValidationSupport(contexto),
                new CommonCodeSystemsTerminologyService(contexto));
        validador = contexto.newValidator();
        validador.registerValidatorModule(new FhirInstanceValidator(apoio));
    }

    private List<SingleValidationMessage> erros(String recursoSerializado) {
        return validador.validateWithResult(recursoSerializado).getMessages().stream()
                .filter(m -> m.getSeverity() == ResultSeverityEnum.ERROR
                        || m.getSeverity() == ResultSeverityEnum.FATAL)
                .toList();
    }

    private String serializar(Patient paciente) {
        return contexto.newJsonParser().encodeResourceToString(paciente);
    }

    @Test
    @DisplayName("controle negativo: o validador REPROVA um recurso invalido")
    void validadorReprovaRecursoInvalido() {
        // gender fora do value set obrigatorio. Se isto passar, o validador nao
        // esta validando nada e todo o resto deste teste e evidencia falsa.
        var invalido = """
                {"resourceType":"Patient","id":"x","gender":"banana"}
                """;

        assertThat(erros(invalido))
                .as("o validador precisa reprovar um recurso sabidamente invalido")
                .isNotEmpty();
    }

    @Test
    @DisplayName("controle positivo: um recurso valido passa")
    void validadorAprovaRecursoValido() {
        assertThat(erros("""
                {"resourceType":"Patient","id":"x","gender":"female"}
                """)).isEmpty();
    }

    @Test
    @DisplayName("Scenario: os 200 pacientes da base de homologacao passam na validacao")
    void todosOsDuzentosPassam() {
        var todos = servico.alteradosNaJanela(null, null, 1000);
        assertThat(todos).hasSize(200);

        for (var paciente : todos) {
            assertThat(erros(serializar(paciente)))
                    .as("paciente %s reprovado na validacao", paciente.getIdElement().getIdPart())
                    .isEmpty();
        }
    }

    @Test
    @DisplayName("Scenario: recurso sem CPF, sem CNS, sem endereco e sem contato passa na validacao")
    void pacienteSemNadaPassa() {
        var semDocumento = servico.porCodigo(10023).orElseThrow();

        assertThat(semDocumento.getIdentifier()).hasSize(1);
        assertThat(erros(serializar(semDocumento))).isEmpty();
    }

    @Test
    @DisplayName("o paciente com tp_sexo='I' e a extensao de valor bruto passa na validacao")
    void pacienteComSexoIndeterminadoPassa() {
        var indeterminado = servico.porCodigo(10044).orElseThrow();

        assertThat(indeterminado.getGender().toCode()).isEqualTo("unknown");
        assertThat(erros(serializar(indeterminado))).isEmpty();
    }

    @Test
    @DisplayName("o paciente com obito anterior ao nascimento passa na validacao")
    void pacienteComDataImpossivelPassa() {
        var impossivel = servico.porCodigo(10074).orElseThrow();

        assertThat(impossivel.hasDeceased()).isFalse();
        assertThat(erros(serializar(impossivel))).isEmpty();
    }

    @Test
    @DisplayName("Scenario 4.5: os pacientes sem endereco e sem contato produzem recurso valido")
    void pacientesSemEnderecoOuContato() {
        var todos = servico.alteradosNaJanela(null, null, 1000);

        var semEndereco = todos.stream().filter(p -> !p.hasAddress()).toList();
        var semContato = todos.stream().filter(p -> !p.hasTelecom()).toList();

        assertThat(semEndereco).hasSize(20);
        assertThat(semContato).hasSize(9);

        for (var paciente : semEndereco) {
            assertThat(erros(serializar(paciente))).isEmpty();
        }
        for (var paciente : semContato) {
            assertThat(erros(serializar(paciente))).isEmpty();
        }
    }
}

