import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@DisplayName("Requirement: CapabilityStatement e documentacao navegavel")
class CapacidadesEDocumentacaoIT extends BaseIntegracao {

    @LocalServerPort
    int porta;

    private ClienteHttp cliente;

    @BeforeEach
    void preparar() {
        cliente = new ClienteHttp(porta);
    }

    private CapabilityStatement capacidades() throws Exception {
        var resposta = cliente.get("/metadata");
        assertThat(resposta.statusCode()).isEqualTo(200);
        return cliente.interpretar(resposta.body(), CapabilityStatement.class);
    }

    private CapabilityStatement.CapabilityStatementRestResourceComponent paciente() throws Exception {
        return capacidades().getRestFirstRep().getResource().stream()
                .filter(r -> "Patient".equals(r.getType()))
                .findFirst().orElseThrow();
    }

    @Test
    @DisplayName("Scenario: nenhuma interacao de escrita e declarada")
    void nenhumaEscritaDeclarada() throws Exception {
        var declaradas = paciente().getInteraction().stream()
                .map(i -> i.getCode().toCode())
                .toList();

        assertThat(declaradas)
                .doesNotContain("create", "update", "patch", "delete")
                .contains("read");
    }

    @Test
    @DisplayName("Scenario: todo parametro declarado responde")
    void parametrosDeclaradosRespondem() throws Exception {
        var declarados = paciente().getSearchParam().stream()
                .map(CapabilityStatement.CapabilityStatementRestResourceSearchParamComponent::getName)
                .toList();

        assertThat(declarados).contains("_id", "identifier", "name", "birthdate", "_lastUpdated");

        // Cada um responde de fato, e nao apenas consta da declaracao.
        assertThat(cliente.get("/Patient?_id=10001").statusCode()).isEqualTo(200);
        assertThat(cliente.get("/Patient?name=luciana").statusCode()).isEqualTo(200);
        assertThat(cliente.get("/Patient?birthdate=1940-08-04").statusCode()).isEqualTo(200);
        assertThat(cliente.get("/Patient?_lastUpdated=ge2026-01-01").statusCode()).isEqualTo(200);
