    @DisplayName("apenas o recurso Patient e declarado nesta entrega")
    void somentePatient() throws Exception {
        assertThat(capacidades().getRestFirstRep().getResource())
                .extracting(r -> r.getType())
                .containsExactly("Patient");
    }

