    @DisplayName("Scenario 7.5: a documentacao declara o furo da sincronizacao incremental")
    void documentacaoTrazOFuroDaSincronizacao() throws Exception {
        var texto = paciente().getDocumentation();

        assertThat(texto)
                .contains("7%")
                .contains("COALESCE(dt_atualizacao, dt_cadastro)")
                .contains("VARREDURA COMPLETA PERIODICA E OBRIGATORIA")
                .contains("idempotente");
    }

    @Test
    @DisplayName("a documentacao avisa que a busca por nome nao atende o alvo de 800 ms")
    void documentacaoAvisaSobreDesempenho() throws Exception {
        assertThat(paciente().getDocumentation()).contains("800 ms");
    }

    @Test
    @DisplayName("RF-09: a documentacao navegavel esta no ar em /swagger-ui/")
    void swaggerNoAr() throws Exception {
        var pagina = cliente.get("/swagger-ui/index.html");

        assertThat(pagina.statusCode()).isEqualTo(200);
        assertThat(pagina.body()).containsIgnoringCase("swagger");
    }

    @Test
    @DisplayName("/swagger-ui/ na raiz redireciona para a documentacao da fachada")
    void atalhoNaRaiz() throws Exception {
        var resposta = cliente.getAbsoluto("http://localhost:" + porta + "/swagger-ui/");

        assertThat(resposta.statusCode()).isIn(200, 302);
    }

    @Test
    @DisplayName("a especificacao OpenAPI da fachada esta publicada")
    void openApiPublicado() throws Exception {
        assertThat(cliente.get("/api-docs").statusCode()).isEqualTo(200);
    }
}

