 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@DisplayName("Trilha de auditoria e redacao de CPF no log")
class AuditoriaELogIT extends BaseIntegracao {

    private static final String CPF_DE_TESTE = "26716608044";

