        tudo = anexar(contexto.getLogger(Logger.ROOT_LOGGER_NAME), contexto);
        trilha = anexar(contexto.getLogger("auditoria"), contexto);

        // Usa a MESMA regra de conversao declarada em logback-spring.xml, para
        // que o teste veja a linha como ela sai de verdade.
        layout = new PatternLayout();
        layout.setContext(contexto);
        layout.setPattern("%msgSanitizada");
        layout.start();
    }

    private static ListAppender<ILoggingEvent> anexar(Logger logger, LoggerContext contexto) {
        var appender = new ListAppender<ILoggingEvent>();
        appender.setContext(contexto);
        appender.start();
        logger.addAppender(appender);
        return appender;
    }

    @AfterEach
    void desligarCaptura() {
        var contexto = (LoggerContext) LoggerFactory.getILoggerFactory();
        contexto.getLogger(Logger.ROOT_LOGGER_NAME).detachAppender(tudo);
        contexto.getLogger("auditoria").detachAppender(trilha);
    }

    private List<String> linhasRenderizadas(ListAppender<ILoggingEvent> appender) {
        return appender.list.stream().map(layout::doLayout).toList();
    }

    private void buscarPorCpf() throws Exception {
        var corpo = "identifier=" + URLEncoder.encode(Sistemas.CPF + "|" + CPF_DE_TESTE,
                StandardCharsets.UTF_8);
        assertThat(cliente.buscaPorFormulario(corpo).statusCode()).isEqualTo(200);
    }

    @Test
    @DisplayName("Scenario: nenhuma linha de log de um fluxo completo por CPF contem os digitos")
    void nenhumaLinhaTrazOCpf() throws Exception {
        buscarPorCpf();

        var linhas = linhasRenderizadas(tudo);
        assertThat(linhas).isNotEmpty();
        assertThat(linhas).as("CPF vazou no log").noneMatch(l -> l.contains(CPF_DE_TESTE));
    }

    @Test
    @DisplayName("a redacao do layout pega ate um log escrito sem cuidado")
    void redacaoPegaLogDescuidado() {
        LoggerFactory.getLogger("teste.descuidado")
                .info("consultando o paciente de CPF {}", CPF_DE_TESTE);

        var linhas = linhasRenderizadas(tudo);

        assertThat(linhas).anyMatch(l -> l.contains(LogSanitizador.MARCA));
        assertThat(linhas).noneMatch(l -> l.contains(CPF_DE_TESTE));
    }

    @Test
    @DisplayName("Scenario: leitura registrada com consumidor, paciente e operacao")
    void leituraRegistrada() throws Exception {
        assertThat(cliente.get("/Patient/10001").statusCode()).isEqualTo(200);

        assertThat(linhasRenderizadas(trilha))
                .anyMatch(l -> l.contains("consumidor=vitaflow-testes")
                        && l.contains("operacao=read")
                        && l.contains("paciente=10001"));
    }

    @Test
    @DisplayName("Scenario: busca registrada pelos pacientes devolvidos, sem o CPF usado como criterio")
    void buscaRegistradaSemCriterioSensivel() throws Exception {
        buscarPorCpf();

        var linhas = linhasRenderizadas(trilha);

        assertThat(linhas).anyMatch(l -> l.contains("operacao=search") && l.contains("10001"));
        assertThat(linhas).noneMatch(l -> l.contains(CPF_DE_TESTE));
    }

    @Test
    @DisplayName("a recusa de CPF em URL e registrada sem o valor recusado")
    void recusaRegistradaSemValor() throws Exception {
        assertThat(cliente.get("/Patient?identifier=" + CPF_DE_TESTE).statusCode()).isEqualTo(400);

        var linhas = linhasRenderizadas(trilha);
        assertThat(linhas).anyMatch(l -> l.contains("motivo=cpf-em-url"));
        assertThat(linhas).noneMatch(l -> l.contains(CPF_DE_TESTE));
    }

    @Test
    @DisplayName("a recusa de nome da mae e registrada sem o valor recusado")
    void recusaDeNomeDaMaeRegistrada() throws Exception {
        assertThat(cliente.get("/Patient?mothersMaidenName=Cristiane").statusCode()).isEqualTo(400);

        var linhas = linhasRenderizadas(trilha);
        assertThat(linhas).anyMatch(l -> l.contains("motivo=nome-da-mae-fora-de-escopo"));
        assertThat(linhas).noneMatch(l -> l.contains("Cristiane"));
    }
}

