package br.com.vitaflow.fhirfacade.desempenho;

import static org.assertj.core.api.Assertions.assertThat;

import br.com.vitaflow.fhirfacade.apoio.BaseIntegracao;
import br.com.vitaflow.fhirfacade.apoio.ClienteHttp;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;

/**
 * RNF-04: 800 ms no percentil 95 para consulta por identificador.
 *
 * <p>A leitura por identificador tem que cumprir. A busca por nome NAO cumpre, e
 * o numero medido e registrado em vez de omitido — RA-02 proibe instalar
 * unaccent, entao a insensibilidade a acento custa varredura completa.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@DisplayName("Desempenho medido")
class DesempenhoIT extends BaseIntegracao {

    private static final Logger log = LoggerFactory.getLogger(DesempenhoIT.class);
    private static final Path RELATORIO = Path.of("target", "medicoes-desempenho.md");

    @LocalServerPort
    int porta;

    private ClienteHttp cliente;

    @BeforeEach
    void preparar() {
        cliente = new ClienteHttp(porta);
    }

    private static long percentil95(List<Long> amostras) {
        var ordenadas = new ArrayList<>(amostras);
        ordenadas.sort(Long::compareTo);
        var posicao = (int) Math.ceil(0.95 * ordenadas.size()) - 1;
        return ordenadas.get(Math.max(0, posicao));
    }

    private long medir(String caminho) throws Exception {
        var comeco = System.nanoTime();
        var resposta = cliente.get(caminho);
        var fim = System.nanoTime();
        assertThat(resposta.statusCode()).isEqualTo(200);
        return (fim - comeco) / 1_000_000;
    }

    private static void registrar(String linha) throws Exception {
        Files.createDirectories(RELATORIO.getParent());
        if (!Files.exists(RELATORIO)) {
            Files.writeString(RELATORIO, """
                    # Medicoes de desempenho — fachada FHIR Paciente

                    Medido contra a base de homologacao (200 pacientes). Producao tem
                    cerca de 480 mil, e a busca por nome escala linearmente com isso.

                    """);
        }
        Files.writeString(RELATORIO, linha + System.lineSeparator(),
                java.nio.file.StandardOpenOption.APPEND);
        log.info(linha);
    }

    @Test
    @DisplayName("9.2 — leitura por identificador logico cumpre os 800 ms no p95")
    void leituraPorIdentificadorCumpreRnf04() throws Exception {
        // Aquecimento: nao se mede JIT frio como se fosse latencia de producao.
        for (int i = 0; i < 20; i++) {
            medir("/Patient/10001");
        }

        var amostras = new ArrayList<Long>();
        for (int codigo = 10001; codigo <= 10200; codigo++) {
            amostras.add(medir("/Patient/" + codigo));
        }

        var p95 = percentil95(amostras);
        registrar("- Leitura por identificador logico (`GET /Patient/{id}`), "
                + amostras.size() + " leituras distintas: **p95 = " + p95 + " ms** — "
                + "alvo RNF-04 de 800 ms: **cumprido**.");

        assertThat(p95)
                .as("RNF-04: leitura por identificador no percentil 95")
                .isLessThan(800);
    }

    @Test
    @DisplayName("9.3 — busca por nome e medida e registrada como nao conforme ao RNF-04")
    void buscaPorNomeEhMedidaERegistrada() throws Exception {
        for (int i = 0; i < 5; i++) {
            medir("/Patient?name=silva");
        }

        var amostras = new ArrayList<Long>();
        for (var termo : List.of("silva", "santos", "a", "sergio", "maria", "oliveira",
                "nascimento", "correia", "e", "o")) {
            amostras.add(medir("/Patient?name=" + termo));
        }

        var p95 = percentil95(amostras);
        registrar("- Busca por nome (`GET /Patient?name=`), " + amostras.size()
                + " termos: **p95 = " + p95 + " ms** sobre 200 registros. "
                + "**NAO CONFORME ao RNF-04** por decisao registrada na spec: a "
                + "insensibilidade a acentuacao exigida pelo RF-03 e resolvida na "
                + "aplicacao porque RA-02 proibe instalar `unaccent` no banco do "
                + "fornecedor. O custo e varredura completa do cadastro — em producao, "
                + "cerca de 480 mil registros por busca, e nao 200.");

        // O numero existe e foi registrado. O teste NAO exige que cumpra 800 ms:
        // exigir isso seria fingir que a restricao RA-02 nao existe.
        assertThat(amostras).isNotEmpty();
        assertThat(Files.readString(RELATORIO)).contains("NAO CONFORME ao RNF-04");
    }

    @Test
    @DisplayName("a nao conformidade tambem esta declarada na documentacao da interface")
    void naoConformidadeDeclaradaNaInterface() throws Exception {
        var capacidades = cliente.interpretar(cliente.get("/metadata").body(),
                org.hl7.fhir.r4.model.CapabilityStatement.class);

        var documentacao = capacidades.getRestFirstRep().getResource().stream()
                .filter(r -> "Patient".equals(r.getType()))
                .findFirst().orElseThrow()
                .getDocumentation();

        assertThat(documentacao)
                .contains("varredura completa")
                .contains("800 ms");
    }
}

